const gardenShop=[["garnet", "Garnet", 300], ["sapphire", "Sapphire", 300], ["emerald", "Emerald", 300], ["citrine", "Citrine", 300], ["river", "River", 80], ["tree", "Tree Cluster", 60], ["walkway", "Walkway", 45], ["meadow", "Flower Meadow", 25], ["shrub", "Shrub Patch", 30], ["rock", "Rock Formation", 35], ["grass", "Grass Details", 20], ["wildflowers", "Wildflower Patch", 10], ["bench", "Garden Bench", 15], ["lanterns", "Path Lanterns", 20], ["picnic", "Picnic Spot", 25], ["bridge", "Footbridge", 30], ["vegetables", "Community Garden", 40], ["cafe", "Café Cart", 55], ["stage", "Music Stage", 70], ["cottage", "Cottage Expansion", 90], ["hall", "Community Hall", 120]];
const gardenSpriteFrames={"currency":[315,1069,176,146],"garnet": [55, 90, 200, 190], "sapphire": [300, 90, 195, 190], "emerald": [540, 90, 195, 190], "citrine": [775, 90, 195, 190], "river": [1000, 80, 225, 230], "tree": [35, 310, 230, 235], "walkway": [285, 315, 225, 230], "meadow": [510, 350, 240, 195], "shrub": [750, 345, 230, 200], "rock": [995, 345, 235, 200], "grass": [40, 560, 220, 210], "wildflowers": [285, 570, 225, 200], "bench": [515, 570, 225, 200], "lanterns": [760, 560, 225, 210], "picnic": [995, 575, 235, 195], "bridge": [40, 800, 230, 200], "vegetables": [285, 800, 225, 200], "cafe": [520, 780, 225, 220], "stage": [760, 790, 225, 210], "cottage": [995, 790, 235, 210], "hall": [35, 1015, 230, 190], "pebble": [300, 1020, 200, 185]};
