// Render the reference atlas at a deliberately low logical resolution, then upscale without smoothing.
const gardenAtlasImage=document.createElement('img');gardenAtlasImage.onload=()=>paintGardenSprites();gardenAtlasImage.src='assets/garden-sprites-v1.png';
function paintGardenSprites(root=document){paintOriginalGardens();if(!gardenAtlasImage.complete||!gardenAtlasImage.naturalWidth)return;root.querySelectorAll('canvas[data-garden-sprite]').forEach(canvas=>{if(canvas.dataset.painted)return;const frame=gardenSpriteFrames[canvas.dataset.gardenSprite]||gardenSpriteFrames.pebble,scale=gardenAtlasImage.naturalWidth/1280,ctx=canvas.getContext('2d');if(!ctx)return;const ratio=Math.min(canvas.width/frame[2],canvas.height/frame[3]),w=Math.round(frame[2]*ratio),h=Math.round(frame[3]*ratio);ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(gardenAtlasImage,frame[0]*scale,frame[1]*scale,frame[2]*scale,frame[3]*scale,Math.floor((canvas.width-w)/2),Math.floor((canvas.height-h)/2),w,h);canvas.dataset.painted='true'})}
function gardenSprite(id,cls=''){const motion=['pebble','garnet','sapphire','emerald','citrine'].includes(id)?'breathe':['tree','shrub','grass','meadow','wildflowers','vegetables'].includes(id)?'wind':id==='river'?'water':'',size=motion==='breathe'||id==='currency'?32:['tree','shrub','grass','meadow','wildflowers','vegetables','rock'].includes(id)?40:48;return `<span class="garden-sprite ${cls}" data-kind="${id}" data-motion="${motion}" aria-hidden="true"><canvas width="${size}" height="${size}" data-garden-sprite="${id}" data-atlas="assets/garden-sprites-v1.png"></canvas></span>`}

function toggleGardenMotion(){S.gardenMotionPaused=!S.gardenMotionPaused;paintOriginalGardens();document.querySelectorAll('.garden-live').forEach(el=>el.classList.toggle('motion-paused',S.gardenMotionPaused));document.querySelectorAll('[data-garden-motion]').forEach(el=>{el.textContent=S.gardenMotionPaused?'Play motion':'Pause motion';el.setAttribute('aria-pressed',String(S.gardenMotionPaused))})}
function gardenMotionButton(){return `<button class="garden-motion-toggle" data-garden-motion aria-pressed="${Boolean(S.gardenMotionPaused)}" onclick="toggleGardenMotion()">${S.gardenMotionPaused?'Play motion':'Pause motion'}</button>`}
// The previous flat garden has been replaced by the independently layered sky scene.
function paintOriginalGardens(){}

function gardenBuildCatalog(){return gardenCategories.map(([category,start,end])=>`<section class="garden-catalog-category"><h3>${category}</h3>${gardenShop.slice(start,end).map(([id,name,cost])=>`<div class="builditem"><div class="row"><span class="garden-shop-art">${gardenSprite(id)}</span><div><b>${name}</b><br><small>${cost} Pebbles${S.decor.some(x=>x.icon===id)?' · Owned':''}</small></div></div><button class="btn light small" ${S.balance<cost?'disabled':''} onclick="buy('${id}','${name}',${cost})">${S.balance<cost?'Need '+(cost-S.balance):'Build'}</button></div>`).join('')}</section>`).join('')}
// Website entry and app entry stay separate; app shells can use ?app=1.
const entryParams=new URLSearchParams(typeof location!=='undefined'?location.search:'');
const appEntry=entryParams.get('app')==='1';
const publicEventsEntry=entryParams.get('view')==='events';
const authPages=['Auth','Login','Register','Recovery','Onboarding','GooglePreview'];
const authEntry=authPages.find(p=>p.toLowerCase()===entryParams.get('view'));
const legalEntry=['Privacy','Terms'].find(p=>p.toLowerCase()===entryParams.get('view'));
const S={page:legalEntry||authEntry||(publicEventsEntry?'Events':appEntry?'Garden':'welcome'),mode:'Friends',tab:'Discover',guest:publicEventsEntry,balance:240,queue:false,allowExistingGroups:false,recommendationsEnabled:true,dating:true,locationPermission:'prompt',locationAccess:false,proposal:'Pending',likes:['Alex','Sam'],datingQueue:['Maya','Alex','Sam','Jordan'],datingHistory:[],connections:[],interests:['Coffee','Live music','Outdoors'],days:['Wed','Fri'],areas:{Profile:'Ann Arbor, MI',Friends:'University of Michigan',Dating:'Ann Arbor, MI'},radii:{Profile:5,Friends:5,Dating:10},decor:[],day:6,messages:['Hey! That coffee spot looks so good ☕','Right? Want to go after class on Friday?'],name:'Jamie',bio:'Collecting little moments & finding my people.',eventFilter:'All',state:'Populated',candidate:0};
const portraits={Maya:'assets/maya.jpg',Alex:'assets/alex.jpg',Sam:'assets/sam.jpg',Jordan:'assets/jordan.jpg'};
function portrait(n,cls=''){if(n===S.name&&S.photoRemoved)return AccountUI.avatar(cls);return `<img class="portrait ${cls}" src="${n===S.name?(S.profilePhoto||portraits.Sam):(portraits[n]||portraits.Sam)}" alt="${esc(n)} · sample profile" loading="lazy">`}
function uiIcon(paths){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`}
const modeIcons={Friends:uiIcon('<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M21 21v-2a6 6 0 0 0-4-5.65"/>'),Dating:uiIcon('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>')};
const icons={Garden:uiIcon('<path d="M12 21v-9M12 16C5 16 3 12 3 6c6 0 9 3 9 8M12 12c0-6 3-9 9-9 0 6-3 9-9 9"/>'),Events:uiIcon('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2M8 18h2"/>'),Discover:uiIcon('<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>'),Messages:uiIcon('<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9.5 9.5 0 0 1-4-.9L3 21l1.9-5.5a9.5 9.5 0 0 1-.9-4A8.5 8.5 0 0 1 12.5 3h.5a8.5 8.5 0 0 1 8 8v.5Z"/>'),Profile:uiIcon('<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>')};
const utilityIcons={activity:uiIcon('<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>'),settings:uiIcon('<path d="m9 3-.6 2.2-2 .9-2-.6L2 9.5 3.5 11v2L2 14.5l2.4 4 2-.6 2 .9L9 21h6l.6-2.2 2-.9 2 .6 2.4-4-1.5-1.5v-2L22 9.5l-2.4-4-2 .6-2-.9L15 3H9Z"/><circle cx="12" cy="12" r="3"/>')};;const events=[['picnic','🌿','Sunset picnic on the Diag','FRI, OCT 23 · 5:30 PM','Outdoors','The Diag · Campus area','24 going'],['music','♫','Little stage, big energy','SAT, OCT 24 · 7:00 PM','Music','Student Union · Campus area','38 going'],['pottery','🏺','Clay, coffee & new friends','SUN, OCT 25 · 11:00 AM','Creative','Arts Center · Campus area','12 going']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}
function go(p){if(AccountUI.interceptNavigation(p))return;if(p==='Messages'&&S.page!=='Messages')S.chatId=null;S.page=p==='Home'?'Garden':p==='Matchmaking'?'Discover':p;modal.close();render();window.scrollTo(0,0)}function btn(t,action,cl=''){return `<button class="btn ${cl}" onclick="${action.replaceAll('&','&amp;').replaceAll('"','&quot;')}">${t}</button>`}function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${sub}</div><h2>${title}</h2></div>${action}</div>`}function tabs(items,val,fn){return `<div class="tabs">${items.map(x=>`<button class="${x===val?'active':''}" onclick="${fn}('${x}')">${x}</button>`).join('')}</div>`}function setMode(m){if(!['Friends','Dating'].includes(m)||S.mode===m)return;const previous=S.mode,indicator=$('.mode-toggle-indicator'),from=indicator?(window.getComputedStyle?.(indicator)?.transform||(previous==='Dating'?'translateX(100%)':'translateX(0)')):null,keepFocus=Boolean(document.activeElement?.closest?.('.mode-toggle'));S.mode=m;S.tab='Discover';render();const next=$('.mode-toggle-indicator');if(from&&next?.animate&&!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches){next.animate([{transform:from,backgroundColor:previous==='Dating'?'#64444d':'#524c3d'},{transform:m==='Dating'?'translateX(100%)':'translateX(0)',backgroundColor:m==='Dating'?'#64444d':'#524c3d'}],{duration:220,easing:'cubic-bezier(.22,1.12,.36,1)'});$(`.mode-toggle button[data-mode="${m}"] .ui-icon`)?.animate?.([{transform:'scale(.8) rotate(-9deg)'},{transform:'scale(1.15) rotate(5deg)',offset:.55},{transform:'scale(1) rotate(0deg)'}],{duration:300,easing:'cubic-bezier(.2,.8,.3,1)'})}if(keepFocus)$(`.mode-toggle button[data-mode="${m}"]`)?.focus({preventScroll:true})}function setTab(t){S.tab=t;render()}function safety(name){AccountUI.safety(name)}
function render(){if(['Privacy','Terms'].includes(S.page)){app.innerHTML=legalPage(S.page);return}if(authPages.includes(S.page)){app.innerHTML=authPage(S.page);paintGardenSprites();return}const publicView=S.page==='welcome'||(S.guest&&S.page==='Events');app.innerHTML=`${S.page==='welcome'?landing():`<div class="shell ${publicView?'public-shell':''}">${publicView?'':`<nav aria-label="Main navigation">${Object.keys(icons).map(p=>`<button class="${S.page===p?'active':''}" ${S.page===p?'aria-current="page"':''} onclick="go('${p}')"><span>${icons[p]}</span>${p}</button>`).join('')}<div class="sub">${['Matches & Plans','Activity','Settings'].map(p=>`<button onclick="go('${p}')">${p}</button>`).join('')}</div></nav>`}<main class="${S.page==='Garden'?'sky-garden-main':S.page==='Discover'?'mobile-dating-main':''}">${page()}</main></div>`}`;if(S.activeGroupSheet&&modal.open)openActiveGroupSearch();paintGardenSprites();if(S.page==='Garden')SkyGarden.mount(S)}


function welcomeVisual(){const dating=S.welcomeMode==='Dating',name=dating?'Maya':'Alex';return `<div class="welcome-preview-mode" role="group" aria-label="Preview a matching mode">${['Friends','Dating'].map(mode=>`<button aria-pressed="${(S.welcomeMode||'Friends')===mode}" onclick="S.welcomeMode='${mode}';render()">${modeIcons[mode]}${mode}</button>`).join('')}</div><div class="welcome-profile"><img src="${portraits[name]}" alt="${name}, a fictional ${dating?'Dating':'Friends'} profile in the demo"><div class="welcome-profile-shade"></div><div class="welcome-profile-info"><h3>${name}, ${dating?'21':'22'}</h3></div></div>`}
function landing(){return `<div class="welcome-site"><header class="welcome-header"><a class="welcome-wordmark" href="./" aria-label="Pebble home"><img src="assets/pebble-wordmark.svg?v=2" alt="Pebble" width="150" height="66"></a><nav class="welcome-nav" aria-label="Website navigation"><a href="?view=events">Events</a></nav><a class="welcome-open" href="?view=auth">Sign in ${uiIcon('<path d="M7 17 17 7M7 7h10v10"/>')}</a></header><main class="welcome-main"><section class="welcome-hero"><div class="welcome-copy"><h1><span class="welcome-headline-brand">Meet new friends,</span><br>find a date,<br>and make plans.</h1><div class="welcome-actions"><a class="welcome-primary" href="?view=auth">Get started ${uiIcon('<path d="M4 12h16m-6-6 6 6-6 6"/>')}</a><a class="welcome-secondary" href="?view=events">Browse events</a></div></div><div class="welcome-visual">${welcomeVisual()}</div></section><section class="welcome-community" id="welcome-community"><div class="welcome-garden-art"><img src="assets/square-garden-cutout.png" alt="Pebble’s pixel-art floating garden, with a cottage, trees, a stream and friendly Pebble characters" loading="lazy"></div><div class="welcome-community-copy"><h2>Grow your garden</h2></div></section></main><footer class="welcome-footer"><a class="welcome-wordmark" href="./" aria-label="Pebble home"><img src="assets/pebble-wordmark.svg?v=2" alt="Pebble" width="115" height="51"></a><div>${['Privacy','Terms','Safety'].map(x=>`<button onclick="legal('${x}')">${x}</button>`).join('')}</div></footer></div>`}


function page(){if(['Discover','Home','Matchmaking'].includes(S.page))return matchmaking();if(S.page==='Events')return eventPage();if(S.page==='Garden')return garden();if(S.page==='Profile')return profile();if(S.page==='Settings')return settings();if(S.page==='Messages')return messages();if(S.page==='Activity')return activity();if(S.page==='Matches & Plans')return plans();return home()}
function home(){return matchmaking()}

function stateControl(){return `<select style="width:auto;font-size:12px" aria-label="Preview state" onchange="S.state=this.value;render()">${['Populated','Empty','Loading','Error'].map(x=>`<option ${S.state===x?'selected':''}>${x}</option>`).join('')}</select>`}function stateView(){if(S.state==='Populated')return '';return `<div class="card blank"><h2>${S.state==='Empty'?'A little quiet here.':S.state==='Loading'?'Finding your next hello…':'Something got a little tangled.'}</h2><p>${S.state==='Empty'?'Try a wider area or come back later.':S.state==='Loading'?'Loading sample results.':'This is a simulated connection error. Your choices are safe.'}</p>${btn('Try again',"S.state='Populated';render()")}</div>`}
function matchmaking(){return `<div class="discoverhead"><h2>Discover</h2><button class="area-link" onclick="locationSheet(S.mode==='Dating'?'Dating':'Friends')">⌖ ${esc(S.areas[S.mode==='Dating'?'Dating':'Friends'])} ▾</button></div><div class="discovertools"><div class="mode-toggle" role="group" aria-label="Matchmaking mode"><span class="mode-toggle-indicator ${S.mode==='Dating'?'dating':''}" aria-hidden="true"></span>${['Friends','Dating'].map(mode=>`<button type="button" data-mode="${mode}" class="${S.mode===mode?'selected':''}" aria-pressed="${S.mode===mode}" onclick="setMode('${mode}')">${modeIcons[mode]}<span>${mode}</span></button>`).join('')}</div><div class="row">${`<button class="round" aria-label="${S.mode} preferences" title="${S.mode} preferences" onclick="${S.mode==='Dating'?'openDatingPreferences()':'openFriendsPreferences()'}">${uiIcon('<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--bg,#faf7f2)"/><circle cx="15" cy="17" r="3" fill="var(--bg,#faf7f2)"/>')}</button>`}<button class="round" aria-label="Matches and plans" onclick="go('Matches & Plans')">◷</button></div></div>${stateView()||(S.mode==='Dating'?dating():friends())}`}


function archivedActiveFriendsView(){return `<div class="discovery-layout"><section>${S.friendMatch?friendMatchCard():''}${recommendations()}${friendQueuePanel()}</section><details class="card filter-panel" ${S.filtersOpen?'open':''} ontoggle="S.filtersOpen=this.open"><summary>Friends filters <span>⌄</span></summary><div class="filter-content"><label>Search area</label>${btn(S.areas.Friends,"locationSheet('Friends')",'light small')}${ageSlider('Friends')}<label>Friendship goal</label><select><option>Hangout crew</option><option>Study buddies</option><option>Activity partners</option></select><div class="friend-count"><div class="age-heading"><label for="friend-count-slider">New friends</label><output id="friend-count-value" for="friend-count-slider">${S.friendCount||3}</output></div><input id="friend-count-slider" type="range" min="1" max="8" step="1" value="${S.friendCount||3}" aria-valuetext="${S.friendCount||3} new friends" oninput="S.friendCount=+this.value;$('#friend-count-value').textContent=this.value;this.setAttribute('aria-valuetext',this.value+' new friends')"><div class="age-endpoints" aria-hidden="true"><span>1</span><span>8</span></div></div><label class="existing-group-preference"><input type="checkbox" ${S.allowExistingGroups?'checked':''} onchange="S.allowExistingGroups=this.checked"> Join existing groups</label><label>Interests · shared with Profile</label>${interestChips()}<label>Availability</label>${days()}${btn('Save filters',"toast('Filters saved. Search status unchanged.')",'small')}</div></details></div>`}


function interestChips(){return ['Coffee','Live music','Outdoors','Art','Gaming','Fitness','Reading',...S.interests.filter(x=>!['Coffee','Live music','Outdoors','Art','Gaming','Fitness','Reading'].includes(x))].map(x=>`<button class="chip ${S.interests.includes(x)?'selected':''}" onclick="toggleInterest(${esc(JSON.stringify(x))})">${esc(x)}</button>`).join('')+`<button class="chip" onclick="customInterest()">+ Custom</button>`}function toggleInterest(x){if(S.interests.includes(x))S.interests=S.interests.filter(y=>y!==x);else if(S.interests.length<5)S.interests.push(x);else toast('Choose up to five interests');render()}function customInterest(){show('Your own thing',`<label>Custom interest</label><input id="custom" maxlength="25">${btn('Add interest',"addInterest()")}`)}function addInterest(){const v=$('#custom').value.trim();if(v&&S.interests.length<5&&!S.interests.some(x=>x.toLowerCase()===v.toLowerCase())){S.interests.push(v);modal.close();render()}else toast('Choose up to five interests')}const availabilityDays=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const availabilityPickerDays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const availabilityBlocks=[['Morning','6 am–12 pm'],['Afternoon','12–5 pm'],['Evening','5–9 pm'],['Late night','9 pm–2 am']];
S.availability=Object.fromEntries(availabilityDays.map(d=>[d,{blocks:S.days.includes(d)?['Afternoon']:[],custom:null}]));
let availabilityDraft,availabilityDay='Mon';
const availabilityDialog=document.createElement('dialog');availabilityDialog.className='availability-sheet';availabilityDialog.setAttribute('aria-label','Edit weekly availability');document.body.appendChild(availabilityDialog);
function availabilitySummary(){const groups=new Map();for(const day of availabilityDays){const entry=S.availability[day],words=entry.blocks.map(b=>({'Morning':'mornings','Afternoon':'afternoons','Evening':'evenings','Late night':'late nights'})[b]);if(entry.custom)words.push(entry.custom.start+'–'+entry.custom.end+(entry.custom.end<entry.custom.start?' (+1 day)':''));if(!words.length)continue;const key=words.join(', ');groups.set(key,[...(groups.get(key)||[]),day])}return [...groups].map(([times,days])=>days.join(', ')+' '+times).join(' · ')||'Not set'}
function days(){const summary=availabilitySummary();return `<div class="availability-row"><p title="${esc(summary)}">${esc(summary)}</p><button class="text-link" aria-label="Edit weekly availability" onclick="editAvailability()">Edit</button></div>`}
function editAvailability(){availabilityDraft=JSON.parse(JSON.stringify(AccountUI.getDraft()?.availability||S.availability));availabilityDay=availabilityDays.find(d=>availabilityDraft[d].blocks.length||availabilityDraft[d].custom)||'Mon';drawAvailability();availabilityDialog.showModal()}
function drawAvailability(){const entry=availabilityDraft[availabilityDay];availabilityDialog.innerHTML=`<header class="availability-header"><h2>Availability</h2><button class="round" aria-label="Cancel availability changes" onclick="availabilityDialog.close()">×</button></header><div class="availability-tabs" role="tablist" aria-label="Day of week">${availabilityPickerDays.map(day=>`<button id="availability-tab-${day}" role="tab" aria-selected="${day===availabilityDay}" aria-controls="availability-day-panel" tabindex="${day===availabilityDay?0:-1}" onclick="selectAvailabilityDay('${day}')" onkeydown="availabilityTabKey(event,'${day}')">${day}<span class="availability-dot ${(availabilityDraft[day].blocks.length||availabilityDraft[day].custom)?'set':''}"></span></button>`).join('')}</div>${AccountUI.availabilityTools()}<section id="availability-day-panel" role="tabpanel" aria-labelledby="availability-tab-${availabilityDay}"><div class="availability-blocks">${availabilityBlocks.map(([name,time],i)=>`<button id="availability-block-${i}" class="availability-block ${entry.blocks.includes(name)?'selected':''}" aria-pressed="${entry.blocks.includes(name)}" onclick="toggleAvailabilityBlock('${name}',${i})"><b>${name}</b><small>${time}</small></button>`).join('')}</div><button class="availability-custom-link" onclick="toggleCustomAvailability()">${entry.custom?'Remove custom hours':'Custom hours'}</button>${entry.custom?`<div class="availability-custom"><div><label for="availability-start">From</label><input id="availability-start" type="time" value="${entry.custom.start}" oninput="changeAvailabilityTime('start',this.value)"></div><div><label for="availability-end">To</label><input id="availability-end" type="time" value="${entry.custom.end}" oninput="changeAvailabilityTime('end',this.value)"></div></div><p id="availability-overnight" class="mini muted">${entry.custom.end<entry.custom.start?'Ends the following day.':''}</p>`:''}<p id="availability-error" class="availability-error" role="alert"></p></section><footer class="availability-footer"><p>Only shared overlaps are visible to others.</p>${btn('Done',"saveAvailability()")}</footer>`}
function selectAvailabilityDay(day){availabilityDay=day;drawAvailability();availabilityDialog.querySelector('#availability-tab-'+day)?.focus()}
function availabilityTabKey(e,day){const i=availabilityPickerDays.indexOf(day);if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selectAvailabilityDay(availabilityPickerDays[e.key==='Home'?0:e.key==='End'?6:(i+(e.key==='ArrowRight'?1:6))%7])}}
function toggleAvailabilityBlock(name,index){const entry=availabilityDraft[availabilityDay];entry.blocks=entry.blocks.includes(name)?entry.blocks.filter(b=>b!==name):availabilityBlocks.map(b=>b[0]).filter(b=>b===name||entry.blocks.includes(b));drawAvailability();availabilityDialog.querySelector('#availability-block-'+index)?.focus()}
function toggleCustomAvailability(){const entry=availabilityDraft[availabilityDay];entry.custom=entry.custom?null:{start:'09:00',end:'10:00'};drawAvailability();availabilityDialog.querySelector(entry.custom?'#availability-start':'.availability-custom-link')?.focus()}
function changeAvailabilityTime(key,value){const entry=availabilityDraft[availabilityDay];entry.custom[key]=value;availabilityDialog.querySelector('#availability-overnight').textContent=entry.custom.start&&entry.custom.end&&entry.custom.end<entry.custom.start?'Ends the following day.':'';availabilityDialog.querySelector('#availability-error').textContent=''}
function saveAvailability(){for(const day of availabilityDays){const custom=availabilityDraft[day].custom;if(custom&&(!/^([01]\d|2[0-3]):[0-5]\d$/.test(custom.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(custom.end)||custom.start===custom.end)){availabilityDay=day;drawAvailability();availabilityDialog.querySelector('#availability-error').textContent='Choose different start and end times.';availabilityDialog.querySelector('#availability-start')?.focus();return}}if(AccountUI.isEditing()){AccountUI.setAvailability(availabilityDraft);availabilityDialog.close();render();return}S.availability=JSON.parse(JSON.stringify(availabilityDraft));S.days=availabilityDays.filter(d=>S.availability[d].blocks.length||S.availability[d].custom);availabilityDialog.close();render()}

const datingParticipants=Object.fromEntries(['Maya','Alex','Sam','Jordan'].map(name=>[name,{dating:true}]));
function datingEligible(person){return Boolean(person?.dating)}
function datingActive(){return datingEligible(S)}
function datingOffState(){return `<div class="recommendations-disabled dating-disabled"><h3>Dating is off</h3><p>Turn on to discover dates and be discovered.</p><button class="text-link" onclick="openDatingSettings()">Enable in Settings</button></div>`}
function openDatingSettings(){S.settingsSection='Discovery';go('Settings');$('#dating-toggle')?.scrollIntoView({behavior:'smooth',block:'center'});$('#dating-toggle')?.focus()}
function setDatingEnabled(enabled){if(enabled&&!AccountUI.discoveryReady()){show('Complete your Dating profile',`<p>Add a photo, a display name, and a valid birthdate showing you are 18 or older before enabling Dating.</p>${btn('Edit profile',"AccountUI.edit('basics')")}`);return}S.dating=Boolean(enabled);modal.close();render();$('#dating-toggle')?.focus();toast(S.dating?'Dating on':'Dating off')}
// Fixture-only discovery queue. Arrival never displaces the card at index zero.
function currentDatingCandidate(){return S.datingQueue.find(n=>AccountUI.allowed(n)&&datingEligible(datingParticipants[n]))}
function receiveDatingLike(name){if(!AccountUI.allowed(name))return false;if(!datingActive()||!datingEligible(datingParticipants[name])||S.connections.includes(name))return false;if(S.likes.includes(name))return false;S.likes.push(name);const current=currentDatingCandidate();if(name!==current){S.datingQueue=S.datingQueue.filter(n=>n!==name);S.datingQueue.splice(current?S.datingQueue.indexOf(current)+1:0,0,name)}render();return true}
function simulateIncomingDatingLike(){S.mode='Dating';go('Discover');if(!datingActive()){toast('Enable Dating in Settings first');return}const name=['Jordan','Maya','Alex','Sam'].find(n=>n!==currentDatingCandidate()&&!S.likes.includes(n)&&!S.connections.includes(n));if(name&&receiveDatingLike(name))toast('Sample like added after the current profile');else toast('No new sample likes')}
function finishDatingCandidate(name,kind){if(name!==currentDatingCandidate())return false;S.datingQueue=S.datingQueue.filter(n=>n!==name);S.datingHistory.push({name,kind});return true}
function moveDatingCandidate(step){if(!datingActive())return;if(step<0){const last=S.datingHistory.at(-1);if(!last||last.kind!=='skip'){toast('No skip to undo');return}S.datingHistory.pop();S.datingQueue=[last.name,...S.datingQueue.filter(n=>n!==last.name)]}else{const name=currentDatingCandidate();if(name)finishDatingCandidate(name,'skip')}render();window.scrollTo(0,0)}
function sendDatingLike(name){if(!datingActive()||!datingEligible(datingParticipants[name])){toast('Enable Dating in Settings first');return}if(name!==currentDatingCandidate())return;if(S.likes.includes(name)){mutual(name);return}finishDatingCandidate(name,'like');S.sentDatingLikes=[...new Set([...(S.sentDatingLikes||[]),name])];render();window.scrollTo(0,0);toast('Like sent')}
function passDatingLike(name){if(!datingActive()||name!==currentDatingCandidate())return;finishDatingCandidate(name,'skip');modal.close();render();window.scrollTo(0,0)}
function resetDatingQueue(){S.datingQueue=['Maya','Alex','Sam','Jordan'].filter(n=>!S.connections.includes(n));S.datingHistory=[];render()}
function openDatingPreferences(){show('Dating preferences',datingPrefs());modal.classList.add('dating-preferences-modal')}

