S.friendsQueue=['Maya','Jordan','Alex','Sam'];S.friendsHistory=[];
const friendProfileFixtures=Object.fromEntries(Object.entries(datingProfileFixtures).map(([name,p])=>[name,{...p,bio:{Maya:'Design student, playlist maker, and always up for a bookstore detour. Hoping to meet people for coffee, gallery visits, and everyday campus adventures.',Alex:'Usually outside with a camera or looking for a new trail. Looking for friends to explore with, grab food, and make the most of campus life.',Sam:'Into board games, cooking experiments, and finding a good study spot. Always happy to meet someone who wants to learn something new together.',Jordan:'Architecture student who loves live music and exploring the city. Would love to find friends for shows, creative projects, and low-key hangouts.'}[name],intention:{Maya:'Coffee & creative hangouts',Alex:'Outdoor & activity buddies',Sam:'Study & game-night friends',Jordan:'Music & creative friends'}[name]}]));
function currentFriendCandidate(){return S.friendsQueue.find(n=>AccountUI.allowed(n)&&recommendationEligible(recommendationParticipants[n])&&!(S.friendRequestsSent||[]).includes(n)&&!(n==='Jordan'&&S.friendRequest!=='pending'))}
function moveFriendCandidate(step){if(!recommendationsActive())return;if(step<0){const last=S.friendsHistory.at(-1);if(!last||last.kind!=='skip'){toast('No skip to undo');return}S.friendsHistory.pop();S.friendsQueue=[last.name,...S.friendsQueue.filter(n=>n!==last.name)]}else{const name=currentFriendCandidate();if(!name)return;S.friendsQueue=S.friendsQueue.filter(n=>n!==name);S.friendsHistory.push({name,kind:'skip'})}render();window.scrollTo(0,0)}
function resetFriendsQueue(){S.friendsQueue=['Maya','Jordan','Alex','Sam'];S.friendsHistory=[];render();window.scrollTo(0,0)}
function connectFriendCandidate(name){if(!recommendationsActive()||name!==currentFriendCandidate())return;S.friendsQueue=S.friendsQueue.filter(n=>n!==name);S.friendsHistory.push({name,kind:'request'});if(name==='Jordan'&&S.friendRequest==='pending'){acceptFriendRequest();return}requestFriendConnection(name);window.scrollTo(0,0)}
function toggleFriendPreferenceInterest(interest){toggleInterest(interest);openFriendsPreferences()}
function openFriendsPreferences(){show('Friends preferences',`<p class="account-note">Preferences apply immediately. Shared Profile edits have their own Save action.</p><div class="card formgrid"><div><h3>Who you’d like to meet</h3>${ageSlider('Friends')}<label>Search area</label>${btn(S.areas.Friends,"locationSheet('Friends')",'light')}<label for="friendship-goal">Friendship goal</label><select id="friendship-goal" onchange="S.friendshipGoal=this.value">${['New friends','Hangout friends','Study buddies','Activity partners'].map(x=>`<option ${x===(S.friendshipGoal||'New friends')?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Interests · shared with Profile</label><p class="account-note">${S.interests.map(esc).join(' · ')||'No interests selected'}</p>${btn('Edit shared interests',"AccountUI.editShared('interests')",'light small')}<label>Availability · shared with Profile</label>${days()}${btn('Done',"modal.close();toast('Friends preferences updated')")}</div></div>`);modal.classList.add('dating-preferences-modal')}
function friends(){if(!recommendationsActive())return recommendationOffState();const candidate=currentFriendCandidate();if(!candidate)return `<div class="card blank"><h3>You’re all caught up.</h3><p class="muted">More people will appear here.</p>${btn('Replay sample profiles',"resetFriendsQueue()",'light small')}</div>`;const p=friendProfileFixtures[candidate],incoming=candidate==='Jordan'&&S.friendRequest==='pending';return `<div class="dating-focus friends-focus"><div class="card dating-card friends-card"><div class="photo" style="background-image:linear-gradient(0deg,rgba(20,16,14,.94),rgba(20,16,14,.48) 32%,transparent 70%),url('${portraits[candidate]}')">${incoming?'<span class="dating-incoming-tag friend-incoming-tag">Wants to connect</span>':''}<div class="phototext"><h2>${candidate}, ${p.age}</h2><p>${esc(p.role)} · Campus area<br>${esc(p.intention)}</p></div><button class="photo-more round" aria-label="Block or report" onclick="safety('${candidate}')">${uiIcon('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>')}</button></div>${datingProfileDetails(candidate,'Friends')}<div class="dating-actions">${photoAction('Undo skip','<path d="M3 10h10a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5"/>',"moveFriendCandidate(-1)",'undo')}${photoAction('Skip profile','<path d="m6 6 12 12M6 18 18 6"/>',"moveFriendCandidate(1)")}${photoAction(incoming?'Accept friend request':'Send friend request','<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M19 8v6M16 11h6"/>',`connectFriendCandidate('${candidate}')`,'primary')}</div></div></div>`}
function profileInterestDetail(name,interest){if(!datingProfileFixtures[name]?.interests.includes(interest))return;const shared=S.interests.includes(interest),full=S.interests.length>=5;show(esc(interest),`<p>${shared?`You and ${esc(name)} both enjoy ${esc(interest)}.`:`${esc(name)} enjoys ${esc(interest)}.`}</p><p class="mini muted">Your interests are shared across Profile and Friends.</p>${!shared&&full?'<p class="mini">You have 5 interests. Remove one in Profile to add another.</p>'+btn('Edit your interests',"modal.close();go('Profile')",'light'):btn(shared?'Remove from my interests':'Add to my interests',`updateProfileInterest('${name}','${interest}')`)}`)}
function updateProfileInterest(name,interest){if(!datingProfileFixtures[name]?.interests.includes(interest))return;const shared=S.interests.includes(interest);if(!shared&&S.interests.length>=5){profileInterestDetail(name,interest);return}if(shared)S.interests=S.interests.filter(x=>x!==interest);else S.interests.push(interest);render();profileInterestDetail(name,interest);toast(shared?'Removed from your interests':'Added to your interests')}
function datingProfileDetails(name,mode='Dating'){const p=mode==='Friends'?friendProfileFixtures[name]:datingProfileFixtures[name];if(!p)return '';const shared=p.interests.filter(x=>S.interests.includes(x));const overlap=AccountUI.overlap(p.availability);return `<div class="dating-profile-body"><section class="dating-about" aria-labelledby="dating-about-title"><h3 id="dating-about-title">About ${esc(name)}</h3><p>${esc(p.bio)}</p></section><section aria-labelledby="dating-interests-title"><div class="dating-section-heading"><h3 id="dating-interests-title">Interests</h3>${shared.length?`<span>${shared.length} in common</span>`:''}</div><div class="dating-interest-list">${[...shared,...p.interests.filter(interest=>!shared.includes(interest))].map(interest=>`<button type="button" class="dating-interest ${shared.includes(interest)?'in-common':''}" aria-haspopup="dialog" onclick="profileInterestDetail('${name}','${interest}')">${shared.includes(interest)?uiIcon('<path d="m5 12 4 4L19 6"/>'):''}${esc(interest)}${shared.includes(interest)?'<span class="sr-only"> · shared interest</span>':''}</button>`).join('')}</div></section>${overlap?`<section class="dating-overlap">${uiIcon('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>')}<div><h3>Time in common</h3><p>${esc(overlap)} · Shared availability</p></div></section>`:''}<section class="dating-facts" aria-label="${mode} details"><div><span>Looking for</span><p>${esc(p.intention)}</p></div>${mode==='Dating'?`<div><span>Relationship style</span><p>${esc(p.style)}</p></div>`:''}<div><span>Education</span><p>University of Michigan</p></div><div><span>Languages</span><p>${esc(p.languages)}</p></div></section></div>`}
function dating(){if(!datingActive())return datingOffState();const candidate=currentDatingCandidate();if(!candidate)return `<div class="card blank"><h3>You’re all caught up.</h3><p class="muted">More people will appear here.</p>${btn('Replay sample profiles',"resetDatingQueue()",'light small')}</div>`;return `<div class="dating-focus"><div class="card dating-card"><div class="photo" style="background-image:linear-gradient(0deg,rgba(20,16,14,.94),rgba(20,16,14,.48) 32%,transparent 70%),url('${portraits[candidate]}')">${S.likes.includes(candidate)?'<span class="dating-incoming-tag">♡ Likes you</span>':''}<div class="phototext"><h2>${candidate}, ${datingProfileFixtures[candidate].age}</h2><p>${esc(datingProfileFixtures[candidate].role)} · Campus area<br>${esc(datingProfileFixtures[candidate].intention)}</p></div><button class="photo-more round" aria-label="Block or report" title="Block or report" onclick="safety('${candidate}')">${uiIcon('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>')}</button></div>${datingProfileDetails(candidate)}<div class="dating-actions">${photoAction('Undo skip','<path d="M3 10h10a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5"/>',"moveDatingCandidate(-1)",'undo')}${photoAction('Skip profile','<path d="m6 6 12 12M6 18 18 6"/>',"moveDatingCandidate(1)")}${photoAction('Like profile','<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',`sendDatingLike('${candidate}')`,'primary')}</div></div></div>`}


const identityOptions={gender:['Woman','Man','Nonbinary','Prefer not to say','Other'],sexuality:['Straight / Heterosexual','Gay','Lesbian','Bisexual','Pansexual','Asexual','Queer','Prefer not to say','Other']};
S.identity={gender:'Woman',sexuality:'Queer',genderCustom:'',sexualityCustom:'',height:'',visible:{gender:true,sexuality:true,height:false}};
function identitySelector(key,label){return `<label for="identity-${key}">${label}</label><select id="identity-${key}" onchange="updateIdentity('${key}',this.value)">${identityOptions[key].map(value=>`<option value="${value}" ${S.identity[key]===value?'selected':''}>${value}</option>`).join('')}</select><div id="identity-${key}-custom" ${S.identity[key]==='Other'?'':'hidden'}><label for="identity-${key}-text">Describe your ${label.toLowerCase()} (optional)</label><input id="identity-${key}-text" value="${esc(S.identity[key+'Custom'])}" maxlength="80" placeholder="In your own words" oninput="S.identity['${key}Custom']=this.value"></div>`}
function updateIdentity(key,value){if(!identityOptions[key]?.includes(value))return;S.identity[key]=value;$('#identity-'+key+'-custom').hidden=value!=='Other'}
S.ageRanges={Friends:[18,26],Dating:[20,26]};
S.ageFlexible={Dating:false};
S.distanceFlexible={Dating:false};
function ageSlider(mode){const [low,high]=S.ageRanges[mode],left=(low-18)/62*100,right=(high-18)/62*100;return `<div class="age-control" role="group" aria-labelledby="age-label-${mode}"><div class="age-heading"><span id="age-label-${mode}">Age range</span><output id="age-value-${mode}" for="age-low-${mode} age-high-${mode}">${low}–${high}</output></div><div class="age-slider" id="age-slider-${mode}" style="--age-low:${left}%;--age-high:${right}%"><div class="age-track"></div><input id="age-low-${mode}" type="range" min="18" max="80" step="1" value="${low}" aria-label="Minimum age for ${mode}" aria-valuetext="${low} years" oninput="updateAge('${mode}',0,this)"><input id="age-high-${mode}" type="range" min="18" max="80" step="1" value="${high}" aria-label="Maximum age for ${mode}" aria-valuetext="${high} years" oninput="updateAge('${mode}',1,this)"></div><div class="age-endpoints" aria-hidden="true"><span>18</span><span>80</span></div>${mode==='Dating'?`<label class="range-flexibility"><input type="checkbox" ${S.ageFlexible[mode]?'checked':''} onchange="S.ageFlexible['${mode}']=this.checked"><span>Include people slightly outside this range.</span></label>`:''}</div>`}
function updateAge(mode,index,input){const range=S.ageRanges[mode];range[index]=index===0?Math.max(18,Math.min(+input.value,range[1]-1)):Math.min(80,Math.max(+input.value,range[0]+1));input.value=range[index];input.setAttribute('aria-valuetext',range[index]+' years');$('#age-value-'+mode).textContent=range[0]+'–'+range[1];const slider=$('#age-slider-'+mode);slider.style.setProperty('--age-low',(range[0]-18)/62*100+'%');slider.style.setProperty('--age-high',(range[1]-18)/62*100+'%')}
function identityValue(key){return S.identity[key]==='Other'?(S.identity[key+'Custom']||'Other'):S.identity[key]}
function openProfileIdentity(){go('Profile');AccountUI.edit('dating')}
function datingPrefs(){return `<div class="account-preferences"><h3>Who you’d like to meet</h3>${ageSlider('Dating')}<label>Search area</label>${btn(S.areas.Dating,"locationSheet('Dating')",'light')}<label for="dating-targets">Interested in</label><select id="dating-targets" onchange="S.datingTargets=this.value">${['Everyone','Women','Men','Nonbinary people'].map(x=>`<option ${S.datingTargets===x?'selected':''}>${x}</option>`).join('')}</select><p class="account-note">Preferences apply immediately. Dating stays unchanged.</p><div class="account-divider"></div><h3>Your Dating profile</h3><dl class="own-profile-facts"><div><dt>Your intention</dt><dd>${esc(S.datingIntention)}</dd></div><div><dt>Relationship style</dt><dd>${esc(S.relationshipStyle)}</dd></div></dl><button class="profile-identity-link" onclick="openProfileIdentity()">Edit profile details ${uiIcon('<path d="m9 5 7 7-7 7"/>')}</button>${btn('Done',"modal.close();toast('Dating preferences updated')")}</div>`}

function inspect(n,incoming=false){if(n!==S.name&&!AccountUI.allowed(n)){show('Profile unavailable','<p>This profile is unavailable in this demo.</p>');return}if(n===S.name){AccountUI.preview();return}S.safetyTarget=n;if(incoming&&(!datingActive()||!datingEligible(datingParticipants[n]))){show('Dating',datingOffState());return}const chat=chatFixtures.find(c=>!c.groupId&&c.name===n),mode=incoming||chat?.kind==='Dating'?'Dating':'Friends',p=(mode==='Dating'?datingProfileFixtures:friendProfileFixtures)[n];show(`${esc(n)}${p?', '+p.age:''}`,`<div class="row">${portrait(n,'inspect-avatar')}<div>University of Michigan<br><small>Campus area</small></div><button class="round" style="margin-left:auto" aria-label="Block or report ${esc(n)}" onclick="safety()">⋯</button></div>${portrait(n,'inspect-photo')}${p?datingProfileDetails(n,mode):'<p class="section">A member of your Friends group.</p>'}${incoming?`<p class="badge pink">♡ Dating · Likes you</p><div class="row">${btn('Like back',`mutual('${n}')`)}${btn('Pass',`passDatingLike('${n}')`,'light')}</div>`:chat?btn('Message',`openChat('${chat.id}')`,'light'):(S.friendRequestsSent||[]).includes(n)?'<p role="status">Friend request sent</p>':btn('Send Friends request',`requestFriendConnection('${n}');modal.close()`,'light')}`)}
function mutual(n){if(!datingActive()||!datingEligible(datingParticipants[n])){toast('Enable Dating in Settings first');return}if(n!==currentDatingCandidate()||!S.likes.includes(n))return;finishDatingCandidate(n,'match');S.likes=S.likes.filter(x=>x!==n);if(!S.connections.includes(n))S.connections.push(n);render();show('It’s a little spark. ✨',`<span role="img" aria-label="Happy Pebble">${gardenSprite('pebble','mascot')}</span><h2>You and ${n} like each other.</h2><p>Your mutual like is now one Dating connection. Say a little hello.</p>${btn('Send a message ↗',`openMatchedChat('${n}')`)}${btn('Keep exploring',"modal.close()",'light')}`)}
function photoAction(label,paths,action,variant=''){const disabled=variant==='undo'&&((S.mode==='Dating'?S.datingHistory:S.friendsHistory).at(-1)?.kind!=='skip');return `<button class="photo-action ${variant}" ${disabled?'disabled':''} aria-label="${esc(label)}" title="${esc(label)}" onclick="${action.replaceAll('&','&amp;').replaceAll('"','&quot;')}">${uiIcon(paths)}</button>`}
const recommendationParticipants=Object.fromEntries(['Maya','Alex','Sam','Jordan'].map(name=>[name,{recommendationsEnabled:true}]));
function recommendationEligible(person){return Boolean(person?.recommendationsEnabled)}
function recommendationsActive(){return recommendationEligible(S)}
function recommendationOffState(){return `<div class="recommendations-disabled"><h3>Friend recommendations off</h3><p>Turn on to discover friends and be suggested to others.</p><button class="text-link" onclick="openRecommendationSettings()">Enable in Settings</button></div>`}
function openRecommendationSettings(){S.settingsSection='Discovery';go('Settings');$('#recommendations-toggle')?.scrollIntoView({behavior:'smooth',block:'center'});$('#recommendations-toggle')?.focus()}
function setRecommendationsEnabled(enabled){S.recommendationsEnabled=Boolean(enabled);render();$('#recommendations-toggle')?.focus();toast(enabled?'Friend recommendations on':'Friend recommendations off')}

function recommendations(){if(!recommendationsActive())return recommendationOffState();const people=['Maya','Alex'].filter(n=>recommendationEligible(recommendationParticipants[n])&&!(S.dismissedRecommendations||[]).includes(n));const sharedDay=availabilityDays.find(d=>S.availability[d].blocks.length||S.availability[d].custom),shared=sharedDay?sharedDay+' '+(S.availability[sharedDay].blocks[0]?.toLowerCase()||'shared time'):'Flexible timing';return `<div class="recommendations-heading"><h3>Recommended for you</h3><small>Shared interests & free time</small></div><div class="peoplegrid recommendation-people">${people.length?people.map((name,i)=>`<article class="person recommendation-person image-profile-card"><button class="recommendation-profile" onclick="inspect('${name}')" aria-label="View ${name}'s profile">${portrait(name,'like-photo')}<span class="profile-caption"><strong>${name}, ${{Maya:21,Alex:22}[name]}</strong><span>${esc(S.interests[i%Math.max(1,S.interests.length)]||'Meeting new people')}<br>${esc(shared)}</span></span></button><div class="profile-photo-actions">${photoAction('Dismiss '+name,'<path d="m6 6 12 12M6 18 18 6"/>',`S.dismissedRecommendations=[...(S.dismissedRecommendations||[]),'${name}'];render()`)}${(S.friendRequestsSent||[]).includes(name)?`<span class="photo-action sent" role="status" aria-label="Friend request sent to ${name}" title="Request sent">${uiIcon('<path d="m5 12 4 4L19 6"/>')}<span class="sr-only">Request sent</span></span>`:photoAction('Send friend request to '+name,'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M19 8v6M16 11h6"/>',`requestFriendConnection('${name}')`,'primary')}</div></article>`).join(''):`<div class="card blank"><h3>You’re caught up</h3>${btn('Show sample suggestions',"S.dismissedRecommendations=[];render()",'light small')}</div>`}</div>`}

function requestFriendConnection(name){if(!AccountUI.allowed(name)||name===S.name)return;if(!recommendationsActive()){toast('Enable friend recommendations in Settings first');return}S.friendRequestsSent=[...new Set([...(S.friendRequestsSent||[]),name])];render();toast('Friend request sent to '+name)}

function groupDetail(){show('Coffee crew',`<span class="badge">Friends · 3 members</span><div class="item">You</div><div class="item">Maya</div><div class="item">Alex</div><p class="section">Friday · 3–4 pm<br>Student Union area · Coffee & a stroll</p><div class="row">${btn('Open conversation',"openChat('coffee')")}${btn('Review plan',"planEditor()",'light')}</div>`)}

