const eventLocationIcon=uiIcon('<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>');
function setEventCategory(category){S.eventFilter=category;render()}
function eventCards(){const visible=events.filter(e=>(S.eventFilter==='All'||eventPresentation[e[0]].tags.includes(S.eventFilter))&&eventMatchesFilters(e));return visible.length?`<div class="eventgrid event-directory">${visible.map(e=>{const info=eventPresentation[e[0]];return `<button class="event-card" onclick="eventDetail('${e[2]}')" aria-label="${esc(e[2])}: see event and people"><img class="event-image" src="assets/event-${e[0]}.jpg" alt="${info.alt}" loading="lazy"><span class="event-card-body"><span class="event-category">${e[4]}</span><h3>${e[2]}</h3><span class="event-date">${e[3]}</span><span class="event-location">${eventLocationIcon}<span>${e[5]}</span></span><span class="event-card-footer"><span class="event-company">${modeIcons.Friends}<span>${info.company} people looking for company</span></span><span class="event-cta">See event & people ${uiIcon('<path d="M4 12h16m-6-6 6 6-6 6"/>')}</span></span></span></button>`}).join('')}</div>`:`<div class="event-empty"><h3>No events in this category yet</h3><p class="muted">Try another category.</p>${btn('View all events',"setEventCategory('All')",'light')}</div>`}
function eventPage(){return `<section class="events-page">${S.guest?`<div class="public-event-header"><button onclick="go('welcome')" aria-label="Back to Pebble website"><img src="assets/pebble-wordmark.svg?v=2" alt="Pebble" width="115" height="51"></button><a class="welcome-inline-link" href="?view=auth">Sign in ${uiIcon('<path d="M7 17 17 7M7 7h10v10"/>')}</a></div>`:''}${head('Events','',`<button class="btn light event-filter-button" aria-label="Filter events" onclick="eventFilters()">${uiIcon('<path d="M4 7h16M7 12h10M10 17h4"/>')}</button>`)}${S.guest?'<p class="mini muted">Public events</p>':''}<div class="event-categories" role="group" aria-label="Event categories">${['All','Music','Food','Outdoors','Creative','Social','Workshops'].map(x=>`<button aria-pressed="${S.eventFilter===x}" class="${S.eventFilter===x?'selected':''}" onclick="setEventCategory('${x}')">${S.eventFilter===x?uiIcon('<path d="m5 12 4 4L19 6"/>'):''}${x}</button>`).join('')}</div>${S.eventFilters?`<div class="event-filter-summary"><span>${esc([S.eventFilters.when,S.eventFilters.cost,S.eventFilters.area].filter(Boolean).join(' · '))}</span><button onclick="S.eventFilters=null;render()">Clear</button></div>`:''}${stateView()||eventCards()}</section>`}
function eventMatchesFilters(e){const f=S.eventFilters||{};if(f.when==='Today'&&e[0]!=='music')return false;if(f.when==='This weekend'&&e[0]==='picnic')return false;const area=(f.area||'').trim().toLowerCase();return !area||[e[5],'Campus area','Ann Arbor','University of Michigan'].some(x=>x.toLowerCase().includes(area))}
function eventFilters(){const f=S.eventFilters||{when:'This week',cost:'Any price',area:'Campus area'};show('Find your kind of event',`<form onsubmit="event.preventDefault();applyEventFilters()"><label for="event-when">When</label><select id="event-when">${['This week','Today','This weekend'].map(x=>`<option ${x===f.when?'selected':''}>${x}</option>`).join('')}</select><label for="event-cost">Cost</label><select id="event-cost">${['Any price','Free'].map(x=>`<option ${x===f.cost?'selected':''}>${x}</option>`).join('')}</select><label for="event-area">Area</label><input id="event-area" value="${esc(f.area)}" maxlength="100"><p class="mini muted">Sample week: Oct 19–25. All sample events are free.</p><div class="row section"><button class="btn" type="submit">Apply filters</button>${btn('Reset',"S.eventFilters=null;modal.close();render()",'light')}</div></form>`)}
function applyEventFilters(){S.eventFilters={when:$('#event-when').value,cost:$('#event-cost').value,area:$('#event-area').value.trim()};modal.close();render();toast('Event filters applied')}
function toggleEventInterest(id){S.eventInterests??=[];S.eventInterests=S.eventInterests.includes(id)?S.eventInterests.filter(x=>x!==id):[...S.eventInterests,id];eventDetail(events.find(e=>e[0]===id)[2])}
function guestEventAction(){show('Make plans together',`<p>Sign in to save events and connect with people going.</p>${btn('Continue',"auth('Auth')")}${btn('Keep browsing',"modal.close()",'light')}`)}
function eventDetail(n){const e=events.find(e=>e[2]===n);if(!e)return;const info=eventPresentation[e[0]];show(e[2],`<img class="event-image event-detail-image" src="assets/event-${e[0]}.jpg" alt="${info.alt}"><span class="event-category">${e[4]} · Sample event</span><p class="section">${info.description}</p><p><b>${e[3]}</b><br>${e[5]}<br>Free · ${e[6]}</p><div class="event-detail-company">${modeIcons.Friends}<span>${info.company} people looking for company</span></div><div class="row">${btn((S.eventInterests||[]).includes(e[0])?'✓ Interested':'☆ Interested',S.guest?"guestEventAction()":`toggleEventInterest('${e[0]}')`)}${btn('Find a group to go with',S.guest?"guestEventAction()":"show('Event group queue', '<p>Find other people interested in this event. Joining is a separate action from saving interest.</p>'+btn('Join event queue',\"toast('Joined sample event queue; no group match yet')\")+btn('See suggested people',\"S.mode='Friends';go('Matchmaking')\",'light'))",'light')}</div>${btn('Propose a plan',S.guest?"guestEventAction()":"planEditor()",'light small')}`)}
function garden(){return SkyGarden.html(S)}
function selectGardenDay(day){SkyGarden.day(day)}
function buy(icon,name,cost){SkyGarden.purchase(gardenShop.findIndex(item=>item[0]===icon))}function resetGarden(){SkyGarden.resetPurchases()}
function profile(){return AccountUI.profile()}
