function setLocationPermission(status){S.locationPermission=status;S.locationAccess=status==='granted'}
function toggleLocationAccess(input){if(!input.checked){S.locationAccess=false;return}if(S.locationPermission==='granted'){S.locationAccess=true;return}input.checked=false;show('Allow location?',`<span class="badge">Demo permission</span><p class="section">Use your location to suggest nearby people and events. Only general areas are shown.</p><div class="row">${btn('Allow',"resolveLocationPermission('granted')")}${btn('Not now',"resolveLocationPermission('denied')",'light')}</div>`)}
