S.chatId=null;S.chatQuery='';S.friendRequest='pending';
function chatAvatar(c){if(c.groupId)return `<span class="group-avatar">${portrait(S.name)}${friendGroupAvatar(c.group.members.find(p=>p.response==='accepted'))}</span>`;return c.id==='coffee'?`<span class="group-avatar">${portrait('Maya')}${portrait('Alex')}</span>`:portrait(c.name,'contact-avatar')}

function connectionBadge(kind){return `<span class="connection-kind ${kind.toLowerCase()}">${kind}</span>`}
function openChat(id){const c=chatFixtures.find(c=>c.id===id);if(!c||S.leftGroups.includes(id)||!c.groupId&&(!AccountUI.allowed(c.name)||S.hiddenConversations.includes(c.name)))return;S.chatId=id;c.unread=0;S.page='Messages';modal.close();render();scrollChat()}
function scrollChat(){const history=$('#chat-history');if(history)history.scrollTop=history.scrollHeight}
function contactRows(){const q=S.chatQuery.toLowerCase();const found=chatFixtures.filter(c=>(c.groupId?!S.leftGroups.includes(c.id):AccountUI.allowed(c.name)&&!S.hiddenConversations.includes(c.name))&&c.name.toLowerCase().includes(q));return found.length?found.map(c=>`<button class="contact-row ${S.chatId===c.id?'selected':''}" onclick="openChat('${c.id}')" aria-label="Open conversation with ${esc(c.name)}${c.unread?', '+c.unread+' unread messages':''}" ${S.chatId===c.id?'aria-current="true"':''}>${chatAvatar(c)}<span class="contact-copy"><span class="contact-top"><b>${esc(c.name)}</b><small>${c.time}</small></span><span class="contact-bottom"><span class="contact-preview ${c.unread?'unread':''}">${esc(c.history.at(-1)?.text||'Say hello')}</span>${c.unread?`<span class="unread-count">${c.unread}</span>`:''}</span>${connectionBadge(c.kind)}</span></button>`).join(''):'<p class="contact-empty">No conversations found.</p>'}
function filterContacts(value){S.chatQuery=value;$('#contact-list').innerHTML=contactRows()}
function activeGroupSearchEntry(){const match=S.friendMatch,status=S.queue?`Searching · You + ${S.friendSearchCount}`:S.existingGroupOffer?'Group to review':match?.status==='ready'?'Group ready':match?'Review your group':'Find a group',label=S.queue?'Searching':match||S.existingGroupOffer?'Review group':'Find a group';return `<button class="messages-group-action ${S.queue?'is-searching':''}" onclick="openActiveGroupSearch()" aria-label="${status}" title="${status}" ${S.queue?'aria-live="polite"':''}>${uiIcon('<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>')}<span>${label}</span>${match||S.existingGroupOffer?'<i class="group-update-dot" aria-hidden="true"></i>':''}</button>`}

function toggleActiveGroupInterest(interest){toggleInterest(interest);openActiveGroupSearch()}
function openActiveGroupSearch(){show('Find a group',`<span class="badge">Demo · Active matchmaking</span>${S.groupSearchError?'<p class="notice" role="status">No sample people within this age range. Adjust your preferences and try again.</p>':''}${S.friendMatch?friendMatchCard():friendQueuePanel()}${!S.friendMatch&&!S.existingGroupOffer?`<fieldset class="active-group-filters" ${S.queue?'disabled':''}><div class="age-heading"><label for="active-group-size">New friends</label><output id="active-group-size-value" for="active-group-size">You + ${S.friendCount||3}</output></div><input id="active-group-size" type="range" min="1" max="8" step="1" value="${S.friendCount||3}" oninput="S.friendCount=+this.value;$('#active-group-size-value').textContent='You + '+this.value" aria-label="Number of new friends"><p class="mini muted">Your ideal group size. You can start with fewer confirmed members.</p><label class="existing-group-preference"><input type="checkbox" ${S.allowExistingGroups?'checked':''} onchange="S.allowExistingGroups=this.checked"> Open to joining an existing group</label><details><summary>Search preferences</summary>${ageSlider('Friends')}<label>Search area</label>${btn(S.areas.Friends,"locationSheet('Friends')",'light small')}<label>Interests · shared with Profile</label>${interestChips().replaceAll('toggleInterest(', 'toggleActiveGroupInterest(')}<label>Availability · shared with Profile</label>${days()}<p class="mini muted">Only shared time windows and general areas are shown.</p></details></fieldset>`:''}${S.friendMatch?.status==='ready'?`<button class="text-link" onclick="S.friendMatch=null;openActiveGroupSearch()">Start another search</button>`:''}`);S.activeGroupSheet=true}
function messages(){const c=chatFixtures.find(c=>c.id===S.chatId);return `<section class="messaging-page">${head('Messages','',`<div class="row messages-header-actions">${activeGroupSearchEntry()}<button class="round" aria-label="Activity inbox" title="Activity inbox" onclick="go('Activity')">${utilityIcons.activity}</button></div>`)}${stateView()||`<div class="messenger ${c?'has-chat':''}"><aside class="conversation-list"><div class="inbox-search"><label class="sr-only" for="chat-search">Search conversations</label><input id="chat-search" type="search" placeholder="Search" value="${esc(S.chatQuery)}" oninput="filterContacts(this.value)"></div>${S.friendRequest==='pending'?`<button class="requests-link" onclick="friendRequests()"><span>${recommendationsActive()?'Requests':'Requests paused'} <span class="request-count">1</span></span><span>›</span></button>`:''}<div id="contact-list">${contactRows()}</div></aside><section class="conversation ${c?'':'no-conversation'}" aria-label="${c?'Chat with '+esc(c.name):'Select a conversation'}">${c?`<header class="conversation-header"><button class="chat-back" aria-label="Back to conversations" onclick="S.chatId=null;render()">${uiIcon('<path d="m15 18-6-6 6-6"/>')}</button>${chatAvatar(c)}<div class="chat-identity"><b>${esc(c.name)}</b>${connectionBadge(c.kind)}</div><button class="round" aria-label="Conversation options and safety" onclick="chatOptions()">${uiIcon('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>')}</button></header><div id="chat-history" class="chat-history" role="log" aria-live="polite"><div class="chat-date">${c.time==='Yesterday'?'Yesterday':'Today'}</div>${visibleChatHistory(c).map(m=>m.system?`<div class="chat-system">${esc(m.text)}</div>`:`<div class="message-line ${m.mine?'outgoing':'incoming'}">${(c.id==='coffee'||c.groupId)&&!m.mine?`<small class="sender-name">${m.sender||'Alex'}</small>`:''}<div class="message-body">${esc(m.text)}</div><small class="message-meta">${m.time}${m.mine?' · '+(m.read?'Read':'Sent'):''}</small></div>`).join('')}${ACTIVE_FRIEND_MATCHMAKING&&c.groupId?groupGrowthCard(c):''}</div><form class="composer" onsubmit="event.preventDefault();sendMessage()"><label class="sr-only" for="message">Message ${esc(c.name)}</label><input id="message" placeholder="Message…" autocomplete="off" required maxlength="2000"><button class="send-button" aria-label="Send message" type="submit">${uiIcon('<path d="m5 12 7-7 7 7M12 5v14"/>')}</button></form>`:`<div class="conversation-placeholder">${icons.Messages}<p>Select a conversation</p></div>`}</section></div>`}</section>`}
function sendMessage(){const input=$('#message'),c=chatFixtures.find(c=>c.id===S.chatId),v=input?.value.trim();if(!v||!c||!c.groupId&&!AccountUI.allowed(c.name))return;const now=new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});c.history.push({text:v,mine:true,time:now,read:false});c.time='Now';chatFixtures.splice(chatFixtures.indexOf(c),1);chatFixtures.unshift(c);render();scrollChat();$('#message')?.focus()}
function friendRequests(){S.safetyTarget='Jordan';if(!AccountUI.allowed('Jordan')){show('Requests','<p>No pending requests.</p>');return}if(!recommendationsActive()){show('Requests paused',`<p>Turn on friend recommendations to review pending requests.</p>${btn('Open Settings',"openRecommendationSettings()",'light')}`);return}show('Requests',`<div class="request-profile">${portrait('Jordan','contact-avatar')}<div><b>Jordan</b><p class="mini muted">Friends · Photography, outdoors</p></div><button class="round" aria-label="Block or report" onclick="safety()">⋯</button></div><div class="row">${btn('Accept',"acceptFriendRequest()")}${btn('Decline',"S.friendRequest='declined';modal.close();render()",'light')}</div>`)}
function acceptFriendRequest(){if(!AccountUI.allowed('Jordan'))return;AccountUI.prepareConnection('Jordan');if(!recommendationsActive()){friendRequests();return}S.friendRequest='accepted';if(!S.connections.includes('Jordan'))S.connections.push('Jordan');chatFixtures.push({id:'jordan',name:'Jordan',kind:'Friends',time:'Now',unread:0,history:[]});openChat('jordan')}
function defaultGroupName(members){const names=[...new Set(members)].filter(name=>name!==S.name);return names.length?names.join(', ')+' & you':'Your group'}
function renameGroup(){const chat=chatFixtures.find(c=>c.id===S.chatId);if(!chat?.groupId)return;show('Group name',`<label for="group-name">Name</label><input id="group-name" maxlength="60" value="${esc(chat.name)}" autocomplete="off"><p id="group-name-error" class="mini danger" role="alert"></p><div class="row">${btn('Save',"saveGroupName()")}${btn('Cancel',"modal.close()",'light')}</div>`);$('#group-name')?.focus()}
function saveGroupName(){const chat=chatFixtures.find(c=>c.id===S.chatId),name=$('#group-name')?.value.trim().slice(0,60);if(!chat?.groupId)return;if(!name){$('#group-name-error').textContent='Enter a group name';return}chat.name=name;chat.customGroupName=true;modal.close();render();toast('Group name updated')}
function chatOptions(){AccountUI.chatOptions()}

function activity(){return `${head('Your little updates.','ACTIVITY INBOX',stateControl())}${stateView()||`<div class="card">${[(datingActive()?['♡','Dating interest','Incoming likes appear in your profile queue.','Open Dating',"S.mode='Dating';go('Matchmaking')"]:['♡','Dating paused','Enable Dating to see incoming likes.','Open Settings',"openDatingSettings()"]),['♧','Friends request',S.friendRequest==='pending'?'Jordan wants to connect.':'No pending Friends requests.',S.friendRequest==='pending'?'Review request':'Open messages',S.friendRequest==='pending'?"friendRequests()":"go('Messages')"],['✓','Plan update','Your Friday coffee plan is ready to review.','Review plan',"planEditor()"]].map(([i,t,d,b,a])=>`<div class="item row"><span class="avatar">${i}</span><div style="flex:1"><span class="badge ${t.startsWith('Dating')?'pink':'lilac'}">${t}</span><p style="margin:7px 0">${d}</p>${btn(b,a,'light small')}</div></div>`).join('')}</div>`}`}
function plans(){return `<button class="secondary-back" onclick="go('Discover')" aria-label="Back to Discover">${uiIcon('<path d="m14 6-6 6 6 6"/>')}<span>Discover</span></button>${head('From a hello to a “see you there.”','MATCHES & PLANS')}${tabs(['Upcoming','Connections','Past'],S.planTab||'Upcoming','planTab')}<div class="card">${S.planTab==='Connections'?`<h3>Your accepted connections</h3>${S.connections.length?S.connections.map(n=>`<div class="item row">${portrait(n,'inbox-avatar')}<b>${n}</b>${btn('Message',`openConnectionChat('${n}')`,'light small')}</div>`).join(''):'<p>No accepted connections yet. Like back or accept a Friends request to start.</p>'}`:S.planTab==='Past'?`<h3>Campus sketch walk</h3><p>Saturday, Oct 17 · Sample past plan</p>${btn('Follow up with your crew',"go('Messages')",'light')}`:`<span class="badge lilac">${S.confirmed?'Confirmed':'Awaiting review'}</span><h2 class="section">${esc(planData().activity)}</h2><p>${esc(planWhen())} · ${esc(planData().area)}</p><p>You, Maya & Alex · Sample plan</p>${btn('View group',"groupDetail()",'light')}${btn('Review plan',"planEditor()",'light')}`}</div>`}function planTab(t){S.planTab=t;render()}function planData(){return S.planDraft||{activity:'Coffee & a campus stroll',when:'2026-10-30T15:00',area:'Student Union café'}}
function planWhen(p=planData()){const date=new Date(p.when);return Number.isNaN(date.getTime())?'Choose a time':date.toLocaleString('en-US',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function planEditor(){const p=planData();show('Make a little plan',`<span class="badge lilac">Planning design example</span><form onsubmit="event.preventDefault();capturePlan()"><label for="plan-activity">Activity</label><select id="plan-activity">${['Coffee & a campus stroll','Study session','Sunset picnic'].map(x=>`<option ${x===p.activity?'selected':''}>${x}</option>`).join('')}</select><label for="plan-when">When · your local time</label><input id="plan-when" type="datetime-local" value="${esc(p.when)}" required><label for="plan-area">Public meeting area</label><input id="plan-area" value="${esc(p.area)}" maxlength="120" required><p class="mini muted">Share a public meeting point. Private schedules stay private.</p><p id="plan-error" class="account-error" role="alert"></p><button type="submit" class="btn">Review plan</button></form>`)}
function capturePlan(){const area=$('#plan-area').value.trim(),when=$('#plan-when').value;if(!area||!when||Number.isNaN(new Date(when).getTime())){$('#plan-error').textContent='Choose a time and a public meeting area.';return}S.planDraft={activity:$('#plan-activity').value,when,area};S.allAccepted=false;S.confirmed=false;reviewPlan()}
function reviewPlan(){const p=planData();show('Review your plan',`<span class="badge lilac">Planning design example</span><h3 class="section">${esc(p.activity)}</h3><p>${esc(planWhen(p))}<br>${esc(p.area)}<br>You, Maya & Alex</p><div class="notice">${S.allAccepted?'Everyone has accepted in this demo.':'Alex is still pending. Confirmation requires every member to accept.'}</div>${btn(S.allAccepted?'Confirm plan':'Simulate all accepting & confirm',"confirmSamplePlan()")}${btn('Back to edit',"planEditor()",'light')}`)}
function confirmSamplePlan(){S.allAccepted=true;S.confirmed=true;show('Plan confirmed',`<h3>${esc(planData().activity)}</h3><p>${esc(planWhen())}<br>${esc(planData().area)}</p><p class="mini muted">Sample plan only. No invitations or notifications were sent.</p>${btn('View Matches & Plans',"go('Matches & Plans')")}`)}
function show(title,body){S.activeGroupSheet=false;modal.classList.remove('dating-preferences-modal','dating-detail-sheet','account-modal','account-preview-modal','location-modal');modal.setAttribute('aria-labelledby','dialog-title');modal.innerHTML=`<div class="modalhead"><h2 id="dialog-title">${title}</h2><button class="round" aria-label="Close dialog" onclick="modal.close()">×</button></div>${body}`;if(!modal.open)modal.showModal();paintGardenSprites(modal)}
// Isolated authentication fixtures. Replace this adapter when integrating real auth.
// No request, provider, account lookup, password storage, or production session is used.
const demoAuthAdapter={async lookup(email,provider){await new Promise(resolve=>setTimeout(resolve,350));if(email.toLowerCase()==='error@example.com')throw new Error('Sample lookup unavailable. Please try again.');return {email,provider,exists:email.toLowerCase()==='jamie@example.com'}}};
let authRequestId=0;
function auth(type){if(!authPages.includes(type))return;authRequestId++;S.authChecking=false;go(type);if(typeof history!=='undefined')history.replaceState(null,'','?view='+type.toLowerCase())}
function enterDeveloperDemo(){if(S.demoDeleted){location.assign('?app=1');return}AccountUI.syncAccount();authRequestId++;S.authChecking=false;S.guest=false;S.state='Populated';S.activeGroupSheet=false;go('Garden');if(typeof history!=='undefined')history.replaceState(null,'','?app=1')}
async function resolveAuthFixture(email,provider='Email'){if(S.authChecking)return;const request=++authRequestId;S.authChecking=true;const status=$('#auth-status'),button=$('#auth-submit');status.textContent='Checking sample account…';if(button){button.disabled=true;button.setAttribute('aria-busy','true')}try{const result=await demoAuthAdapter.lookup(email.trim(),provider);if(request!==authRequestId||!authPages.includes(S.page))return;S.authFlow=result;S.authChecking=false;auth(result.exists?'Login':'Register')}catch(error){if(request!==authRequestId||!authPages.includes(S.page))return;S.authChecking=false;status.textContent=error.message;if(button){button.disabled=false;button.setAttribute('aria-busy','false')}}}
function submitAuthPreview(event,type){event.preventDefault();if(type==='Auth')return resolveAuthFixture($('#auth-email').value);if(type==='Recovery'){$('#auth-status').textContent='Recovery preview only. No email has been sent.';return}if(type==='Onboarding'){const name=$('#auth-name').value.trim();if(name)S.name=name;enterDeveloperDemo();return}event.target.querySelectorAll('input[type="password"]').forEach(input=>input.value='');if(type==='Register'){auth('Onboarding');return}enterDeveloperDemo()}
function authPage(type){const entry=type==='Auth',login=type==='Login',register=type==='Register',recovery=type==='Recovery',onboarding=type==='Onboarding',googleChoice=type==='GooglePreview',flow=S.authFlow||{},google=flow.provider==='Google',title=entry||register?'Welcome to Pebble':login?'Welcome back':recovery?'Reset your password':googleChoice?'Google sign-in preview':'A little introduction.';return `<div class="auth-page auth-centered"><main class="auth-main"><section class="auth-form-section" aria-labelledby="auth-title"><div class="auth-form-wrap"><a class="auth-centered-logo" href="./" aria-label="Pebble home"><img src="assets/pebble-wordmark.svg?v=2" alt="Pebble" width="170" height="76"></a><h1 id="auth-title">${title}</h1>${googleChoice?`<p class="auth-intro">Choose a fixture account to preview each path. No Google account is accessed.</p><div class="auth-google-choices"><button onclick="resolveAuthFixture('jamie@example.com','Google')"><b>Existing demo account</b><small>jamie@example.com</small></button><button onclick="resolveAuthFixture('new@example.com','Google')"><b>New demo account</b><small>new@example.com</small></button></div><p id="auth-status" class="auth-status" role="status" aria-live="polite"></p>`:`<form onsubmit="submitAuthPreview(event,'${type}')">${onboarding?`<label for="auth-name">Display name</label><input id="auth-name" name="displayName" autocomplete="nickname" value="${esc(S.name)}" required maxlength="50"><label for="auth-purpose">What brings you here?</label><select id="auth-purpose"><option>Friends, dating & events</option><option>Making friends</option><option>Finding community</option></select>`:`<label for="auth-email">Email</label><input id="auth-email" name="email" type="email" inputmode="email" autocomplete="email" autocapitalize="none" spellcheck="false" placeholder="you@example.com" value="${esc(entry||recovery?'':flow.email||'')}" ${google&&(login||register)?'readonly':''} required>${login||register?`${google?`<p class="auth-provider-note">${register?'Create a profile':'Continue'} with your sample Google account.</p>`:`<div class="auth-password-label"><label for="auth-password">${register?'Create password':'Password'}</label>${login?`<button type="button" onclick="auth('Recovery')">Forgot password?</button>`:''}</div><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 8 characters':'Enter your password'}" required ${register?'minlength="8"':''}>`}`:''}`}<button class="auth-submit" id="auth-submit" type="submit">${entry?'Continue with email':login?(google?'Continue with Google':'Sign in'):register?'Create account':recovery?'Preview recovery':'Continue'}</button><p id="auth-status" class="auth-status" role="status" aria-live="polite"></p></form>`}${entry?`<div class="auth-or"><span>or</span></div><button class="auth-google" onclick="auth('GooglePreview')">Continue with Google</button>`:''}${login||register||googleChoice?`<button class="auth-return" onclick="auth('Auth')">${googleChoice?'Back to email':'Use a different email or Google'}</button>`:recovery?`<button class="auth-return" onclick="auth('Login')">Back to sign in</button>`:''}<a class="auth-home-link" href="./">Back to home</a>${onboarding?'':`<div class="auth-dev-section"><p class="auth-dev-label">Design demo</p><button class="auth-dev-button" onclick="enterDeveloperDemo()">Sign in as dev</button><p class="auth-demo-note">Fixture flow only. No real accounts or providers connected.</p>${entry?`<details class="auth-fixture-help"><summary>Preview account paths</summary><p><b>jamie@example.com</b> → existing account<br>Any other email → registration</p></details>`:''}</div>`}<footer class="auth-footer">${['Privacy','Terms','Safety'].map(x=>`<button onclick="legal('${x}')">${x}</button>`).join('')}</footer></div></section></main></div>`}

function legal(t){if(['Terms','Privacy'].includes(t)){if(!['Terms','Privacy'].includes(S.page))S.legalReturn=S.page;go(t);if(S.page!==t)return;if(typeof history!=='undefined')history.replaceState(null,'','?view='+t.toLowerCase());return}show(t,t==='Design notes'?`<p>Event photos: Kyrie Isaac (picnic), Scarlett Alt (music), Sander Breneman (pottery), via Unsplash. Illustrative photos for sample events.<br>Portraits: Unsplash stock photos, used with fictional names and sample profiles. These are not actual members.</p><p>Pebble’s design combines focus-led discovery, expressive profile details, persistent navigation, and contextual safety actions.</p><p>Research references: <a href="https://hinge.co/how-we-connect-daters" target="_blank" rel="noreferrer">Hinge discovery</a>, <a href="https://newsroom.tiktok.com/how-tiktok-recommends-videos-foryou?lang=en-AU" target="_blank" rel="noreferrer">TikTok feed</a>, <a href="https://about.fb.com/news/2020/08/introducing-instagram-reels/" target="_blank" rel="noreferrer">Instagram Explore</a>, <a href="https://tinder.com/en-GB/faq/" target="_blank" rel="noreferrer">Tinder safety</a>.</p><p>All people, balances, histories, messages, matches and plans are fixtures held in memory. Existing authentication and database permissions are untouched.</p>`:`<h3>A little clarity matters.</h3><p>This is a browsable ${t.toLowerCase()} layout example, not a complete legal policy.</p><p>No accounts, real matchmaking, analytics, location requests, geocoding or notification delivery are connected. Sample progress lives only until refresh.</p><h3>Your choices, respected.</h3><p>In the product design, people can manage visibility, discovery and consent, block unwanted connections, and report concerns.</p>`)}
function closeLegalPage(){const target=S.legalReturn||'welcome';go(target);if(typeof history!=='undefined')history.replaceState(null,'',target==='welcome'?'./':authPages.includes(target)?'?view='+target.toLowerCase():target==='Events'&&S.guest?'?view=events':'?app=1')}
function legalPage(type){const doc=legalDocuments[type],links=doc.sections.map(([id,title])=>`<a href="#legal-${id}">${title}</a>`).join('');return `<div class="legal-page"><header class="legal-header"><a href="./" aria-label="Pebble home"><img src="assets/pebble-wordmark.svg?v=2" alt="Pebble" width="135" height="60"></a><button class="legal-back" onclick="closeLegalPage()">${uiIcon('<path d="m14 7-5 5 5 5"/>')} Back</button></header><main class="legal-layout"><aside class="legal-sidebar"><b>On this page</b><nav class="legal-toc" aria-label="On this page">${links}</nav></aside><article class="legal-article"><p class="legal-kicker">Draft for review · No effective date</p><h1>${doc.title}</h1><p class="legal-intro">${doc.intro}</p><div class="legal-draft-note"><b>About this draft</b><p>This is a review draft for the Pebble prototype. Production terms and privacy disclosures need the operator’s confirmed practices and legal review before launch.</p></div><details class="legal-mobile-contents"><summary>On this page</summary><div>${links}</div></details>${doc.sections.map(([id,title,body],i)=>`<section class="legal-section" id="legal-${id}" aria-labelledby="legal-heading-${id}"><h2 id="legal-heading-${id}"><span>${String(i+1).padStart(2,'0')}</span>${title}</h2>${body}</section>`).join('')}<footer class="legal-footer"><button onclick="legal('Terms')" ${type==='Terms'?'aria-current="page"':''}>Terms of Service</button><button onclick="legal('Privacy')" ${type==='Privacy'?'aria-current="page"':''}>Privacy Policy</button><button onclick="closeLegalPage()">Back</button></footer></article></main></div>`}

function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
// Fixture adapter boundary: replace search() and area anchors with a real provider later.
const locationAdapter={search:async q=>places.filter(p=>(p.name+' '+p.context).toLowerCase().includes(q.toLowerCase()))};
const places=[{name:'Ann Arbor, MI',context:'City · Michigan, United States',x:0,y:0},{name:'University of Michigan',context:'Campus · Ann Arbor, MI',x:30,y:-20},{name:'Kerrytown',context:'Neighborhood · Ann Arbor, MI',x:-40,y:30},{name:'Downtown Ann Arbor',context:'Neighborhood · Michigan',x:20,y:40},{name:'Ypsilanti, MI',context:'City · Michigan, United States',x:-70,y:-40},{name:'Eastern Michigan University',context:'Campus · Ypsilanti, MI',x:60,y:20}];let L,timer,locationSearchRevision=0;
function locationSheet(context){clearTimeout(timer);locationSearchRevision++;L={context,name:context==='Profile'&&AccountUI.isEditing()?AccountUI.getDraft().home:S.areas[context],radius:S.radii[context],flexible:context==='Dating'&&Boolean(S.distanceFlexible.Dating),x:S.areaAnchors?.[context]?.x||0,y:S.areaAnchors?.[context]?.y||0,moved:false};show('Choose your area',`<span class="badge">Editing ${context==='Profile'?'Profile home':context+' search area'}</span><p class="mini muted">${context==='Profile'?'Your shared home area.':'Temporary search area. Your Profile home stays unchanged.'}</p><label for="locquery">City, neighborhood or campus</label><input id="locquery" placeholder="Search an area…" autocomplete="off" oninput="searchLocations(this.value)"><div id="suggestions"></div><button class="chip" onclick="currentLocation()">⌖ Use current location</button><div id="locstatus" role="status" class="mini muted"></div><div class="map" id="map" tabindex="0" aria-label="Simulated map. Drag or use arrow keys to adjust the center" onpointerdown="panMap(event)" onkeydown="mapKey(event)"><svg id="mapart" viewBox="0 0 600 400"><rect width="600" height="400" fill="#e6e9e8"/><path d="M0 260Q180 100 240 220T600 180" fill="none" stroke="#afcfe4" stroke-width="45"/><g fill="#c6d9bf"><rect x="60" y="45" width="110" height="75" rx="12"/><rect x="330" y="240" width="100" height="100" rx="15"/><rect x="450" y="60" width="90" height="80" rx="10"/></g><g stroke="#fff" stroke-width="12"><path d="M0 150H600M0 330H600M210 0V400M420 0V400M0 35L600 375"/></g><g fill="#737c7c" font-size="13"><text x="240" y="130">CAMPUS</text><text x="70" y="310">DOWNTOWN</text><text x="440" y="240">THE DIAG</text></g></svg><div class="radius" id="radius"></div><span class="pin">📍</span><span class="maplabel">SIMULATED MAP · Drag to adjust center</span></div><div class="row between"><b id="selectedArea">${L.name}</b><span class="badge" id="radtext">${L.radius} miles</span></div>${context!=='Profile'?`<label for="radiusInput">Matching radius</label><input id="radiusInput" type="range" min="1" max="50" value="${L.radius}" oninput="updateRadius(this.value)">`:''}${context==='Dating'?`<label class="range-flexibility"><input type="checkbox" ${L.flexible?'checked':''} onchange="L.flexible=this.checked"><span>Include people slightly farther away.</span></label>`:''}<p class="mini muted">Fixture search & illustrative map. No external location request or coordinate storage. Area selection is not trusted location proof.</p><div id="anchorConfirm"></div><div class="row">${btn('Use this area',"applyArea()")}${btn('Cancel',"modal.close()",'light')}</div>`);modal.classList.add('location-modal');mapTransform();updateRadius(L.radius);searchLocations('');if(context==='Profile'){$('#radius').style.display='none';$('#radtext').hidden=true}}
async function searchLocations(q){clearTimeout(timer);const revision=++locationSearchRevision,session=L;$('#suggestions').innerHTML='<small role="status">Searching sample places…</small>';timer=setTimeout(async()=>{try{const r=await locationAdapter.search(q);if(revision!==locationSearchRevision||L!==session||!modal.open||!$('#suggestions'))return;$('#suggestions').innerHTML=r.length?r.slice(0,4).map(p=>`<button class="suggest" onclick="choosePlace(${places.indexOf(p)})">⌖ <b>${esc(p.name)}</b><br><small>${esc(p.context)}</small></button>`).join(''):'<p class="mini" role="status">No sample areas found. Try “Ann Arbor”, “campus” or “Kerrytown”.</p>'}catch{if(revision===locationSearchRevision&&L===session&&modal.open&&$('#suggestions'))$('#suggestions').innerHTML='<p class="mini" role="alert">Search unavailable. Try again or choose a sample current location.</p>'}},250)}
function choosePlace(i){const p=places[i];if(!p)return;clearTimeout(timer);locationSearchRevision++;Object.assign(L,{name:p.name,x:p.x,y:p.y,moved:false});$('#selectedArea').textContent=p.name;$('#locquery').value=p.name;$('#suggestions').innerHTML='';$('#anchorConfirm').innerHTML='';mapTransform()}
function mapTransform(){$('#mapart').style.transform=`translate(${L.x}px,${L.y}px)`}function movedAnchor(){L.moved=true;$('#selectedArea').textContent='Adjusted area near '+L.name;$('#anchorConfirm').innerHTML=`<div class="notice">Map center adjusted. Confirm the proposed anchor before applying.<br>${btn('Confirm map center',"L.moved=false;L.name='Near '+L.name.replace(/^Near /,'');$('#selectedArea').textContent=L.name;$('#anchorConfirm').innerHTML='';",'light small')}</div>`;mapTransform()}
function panMap(e){const el=e.currentTarget,x=e.clientX,y=e.clientY,ox=L.x,oy=L.y;el.setPointerCapture(e.pointerId);el.onpointermove=v=>{L.x=ox+v.clientX-x;L.y=oy+v.clientY-y;movedAnchor()};el.onpointerup=el.onpointercancel=()=>{el.onpointermove=null}}function mapKey(e){if(!e.key.startsWith('Arrow'))return;e.preventDefault();L[['ArrowLeft','ArrowRight'].includes(e.key)?'x':'y']+=['ArrowLeft','ArrowUp'].includes(e.key)?-15:15;movedAnchor()}
function updateRadius(v){L.radius=+v;$('#radtext').textContent=v+' miles';const d=90+v*3;$('#radius').style.width=d+'px';$('#radius').style.height=d+'px';$('#radius').style.left=`calc(50% - ${d/2}px)`;$('#radius').style.top=`calc(50% - ${d/2}px)`}function applyArea(){if(L.moved){toast('Confirm the adjusted map center first');return}if(L.context==='Profile'&&AccountUI.isEditing())AccountUI.setDraft('home',L.name);else S.areas[L.context]=L.name;S.radii[L.context]=L.radius;S.areaAnchors??={};S.areaAnchors[L.context]={x:L.x,y:L.y};if(L.context==='Dating')S.distanceFlexible.Dating=L.flexible;modal.close();render();toast(L.context+' area updated')}
function currentLocation(){$('#locstatus').innerHTML=`<div class="notice">Simulate a device permission result. This demo does not request your real location.<br>${btn('Allow sample location',"setLocationPermission('granted');choosePlace(1);$('#locstatus').textContent='Sample current location selected. Confirm to apply.'",'light small')}${btn('Denied',"setLocationPermission('denied');$('#locstatus').textContent='Permission denied. Search manually or try again from your device settings.'",'light small')}${btn('Unavailable',"setLocationPermission('unavailable');$('#locstatus').textContent='Location unavailable. Try selecting a city or campus.'",'light small')}</div>`}
AccountUI.init();
render();

// Review-only navigation lives outside the product shell and fixture state.
const devViews=[['Core views',[['Garden · Home','Garden'],['Landing page','welcome'],['Welcome · email / Google','auth-Auth'],['Login · existing account','auth-Login'],['Registration','auth-Register'],['Terms of Service','legal-Terms'],['Privacy Policy','legal-Privacy'],['Discover','Discover'],['Events · signed in','Events'],['Events · guest','guest-events'],['Messages','Messages'],['Profile','Profile'],['Settings','Settings'],['Settings · Discovery','settings-discovery'],['Settings · Notifications','settings-notifications'],['Settings · Account & security','settings-account'],['Settings · Safety','settings-safety'],['Settings · Privacy & legal','settings-privacy']]],['Matching & community',[['Friends','friends'],['Dating · Discover','dating'],['Dating · Preferences','dating-preferences'],['Pebble garden','Garden'],['Matches & Plans','Matches & Plans'],['Activity inbox','Activity']]],['Flows & examples',[['Event details','event-detail'],['Simulate incoming Dating like','incoming-like'],['Mutual match','mutual-match'],['Friends plan group','group-detail'],['Create a plan','plan-create'],['Review a plan','plan-review'],['Profile home location','location-profile'],['Friends search location','location-friends'],['Dating search location','location-dating'],['Recovery','auth-Recovery'],['Onboarding','auth-Onboarding'],['Safety','legal-Safety'],['Design notes','legal-Design notes']]]];
const devBar=document.createElement('aside');devBar.className='devbar';devBar.setAttribute('aria-label','Development navigation');devBar.innerHTML=`<details id="devdetails"><summary><span class="devdot"></span><b>DEV</b><span class="devcurrent">View navigator</span><span class="devchevron">⌃</span></summary><div class="devpanel"><div class="devtitle"><b>Pebble · Design review</b><small>Fixture data · Changes reset on refresh</small></div><label for="devview">Jump to a view</label><select id="devview"><option value="">Choose a screen…</option>${devViews.map(([group,views])=>`<optgroup label="${group}">${views.map(([label,id])=>`<option value="${id}">${label}</option>`).join('')}</optgroup>`).join('')}</select><label for="devstate">Preview content state</label><select id="devstate"><option>Populated</option><option>Empty</option><option>Loading</option><option>Error</option></select><small class="devhint">Content states apply to Matchmaking, Events, Messages and Activity.</small><div class="devquick"><button data-jump="welcome">Landing page</button><button data-jump="auth-Auth">Sign in</button><button data-jump="Discover">Discover</button><button data-jump="friends">Friends</button><button data-jump="dating">Dating</button><button data-jump="Garden">Garden</button></div></div></details>`;document.body.appendChild(devBar);
function devJump(id){modal.close();S.state=$('#devstate').value;S.guest=false;const modes={friends:['Friends','Discover'],dating:['Dating','Discover'],'dating-preferences':['Dating','Preferences']};if(modes[id]){[S.mode,S.tab]=modes[id];go('Matchmaking');if(id==='dating-preferences')openDatingPreferences()}else if(id==='guest-events'){S.guest=true;go('Events')}else if(id.startsWith('settings-'))AccountUI.openSettings({discovery:'Discovery',notifications:'Notifications',account:'Account & security',safety:'Safety',privacy:'Privacy & legal'}[id.slice(9)]||'');else if(id.startsWith('auth-'))auth(id.slice(5));else if(id.startsWith('legal-'))legal(id.slice(6));else if(id.startsWith('location-'))locationSheet({profile:'Profile',friends:'Friends',dating:'Dating'}[id.slice(9)]);else if(id==='event-detail')eventDetail(events[0][2]);else if(id==='incoming-like')simulateIncomingDatingLike();else if(id==='mutual-match'){S.mode='Dating';go('Discover');const n=currentDatingCandidate();if(n&&datingActive()){if(!S.likes.includes(n))S.likes.push(n);sendDatingLike(n)}}else if(id==='group-detail')groupDetail();else if(id==='plan-create')planEditor();else if(id==='plan-review')reviewPlan();else go(id);$('.devcurrent').textContent=devViews.flatMap(x=>x[1]).find(x=>x[1]===id)?.[0]||id;$('#devview').value=id;$('#devdetails').open=false;}
$('#devview').addEventListener('change',e=>{if(e.target.value)devJump(e.target.value)});$('#devstate').addEventListener('change',e=>{S.state=e.target.value;render();toast('Preview state: '+S.state)});devBar.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>devJump(b.dataset.jump)));

function openConnectionChat(name){const chat=chatFixtures.find(c=>!c.groupId&&c.name===name);if(chat){openChat(chat.id);return}const group=chatFixtures.find(c=>c.groupId&&c.memberNames?.includes(name)&&!S.leftGroups.includes(c.id));if(group){openChat(group.id);return}go('Messages')}
function openMatchedChat(n){AccountUI.prepareConnection(n);let c=chatFixtures.find(c=>c.name===n);if(!c){c={id:n.toLowerCase(),name:n,kind:'Dating',time:'Now',unread:0,history:[]};chatFixtures.unshift(c)}openChat(c.id)}

// Garden editing now lives directly in the camera-driven sky scene.
function openGardenEditor(){SkyGarden.arrange()}
function closeGardenEditor(){SkyGarden.done()}
const friendGroupPeople=[{name:'Maya',age:21},{name:'Alex',age:22},{name:'Sam',age:22},{name:'Jordan',age:23},{name:'Riley',age:21},{name:'Taylor',age:24},{name:'Morgan',age:22},{name:'Casey',age:23}].map(person=>({...person,queued:true,allowExistingGroups:true,minGroupSize:2,maxGroupSize:9}));
function friendGroupAvatar(p,cls=''){return portraits[p.name]?portrait(p.name,cls):`<span class="friend-initial-avatar ${cls}" aria-hidden="true">${p.name.slice(0,1)}</span>`}
function friendQueuePanel(){if(S.existingGroupOffer)return existingOfferCard();if(S.friendMatch)return '';return `<div class="queue-panel friend-search-panel" role="status"><div class="friend-search-icon">${uiIcon('<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>')}</div><div><h3>${S.queue?'Searching…':'Find a group'}</h3><small>${S.queue?`You + ${S.friendSearchCount} new ${S.friendSearchCount===1?'friend':'friends'} · Sample search`:`You + ${S.friendCount||3} new friends`}</small></div><div class="row">${S.queue?`${btn('Check now',"simulateFriendMatch()",'small')}${btn('Cancel',"cancelFriendSearch()",'light small')}`:btn('Find friends',"startFriendSearch()",'small')}</div></div>`}
function startFriendSearch(){if(!ACTIVE_FRIEND_MATCHMAKING)return;S.groupSearchError=false;S.friendSearchCount=Math.max(1,Math.min(8,Number(S.friendCount)||3));S.friendSearchFilters={ages:[...S.ageRanges.Friends],area:S.areas.Friends,radius:S.radii.Friends};S.friendMatch=null;S.existingGroupOffer=null;S.queue=true;const token=S.friendQueueToken=(S.friendQueueToken||0)+1;render();setTimeout(()=>{if(S.queue&&S.friendQueueToken===token)simulateFriendMatch()},2400)}
function cancelFriendSearch(){S.groupSearchError=false;S.queue=false;S.friendQueueToken=(S.friendQueueToken||0)+1;S.friendMatch=null;S.existingGroupOffer=null;modal.close();render()}
function simulateFriendMatch(){if(!S.queue)return;const count=S.friendSearchCount||3;const eligible=friendGroupPeople.filter(p=>AccountUI.allowed(p.name)&&p.queued&&p.age>=S.friendSearchFilters.ages[0]&&p.age<=S.friendSearchFilters.ages[1]);if(!eligible.length){S.queue=false;S.groupSearchError=true;render();return}if(S.allowExistingGroups&&count>=2&&eligible.length>=2){offerExistingGroup(count);return}S.queue=false;S.friendQueueToken=(S.friendQueueToken||0)+1;const availableDay=availabilityDays.find(d=>S.availability[d].blocks.length||S.availability[d].custom);const availability=availableDay?S.availability[availableDay]:null;S.friendMatch={id:'friends-'+S.friendQueueToken,count,searchFilters:{...S.friendSearchFilters,ages:[...S.friendSearchFilters.ages]},status:'review',ownAccepted:false,members:friendGroupPeople.filter(person=>AccountUI.allowed(person.name)&&person.queued&&person.age>=S.friendSearchFilters.ages[0]&&person.age<=S.friendSearchFilters.ages[1]).slice(0,count).map((p,i)=>({...p,response:i<Math.ceil(count/2)?'accepted':'pending'})),interests:S.interests.slice(0,2),overlap:availableDay?availableDay+' '+(availability.blocks[0]?.toLowerCase()||'shared time'):'A flexible meetup time'};render();if(S.page==='Messages')$('#friends-match')?.scrollIntoView({behavior:'smooth',block:'nearest'});toast('Your sample group is ready to review')}
function friendMatchCard(){const m=S.friendMatch,pending=m.members.filter(p=>p.response==='pending').length,accepted=m.members.filter(p=>p.response==='accepted');return `<section id="friends-match" class="friend-match-card" aria-label="Friends group match"><div class="row between"><span class="badge">Friends group</span><small>Demo match</small></div><h3>${m.status==='ready'?'Your group is ready':m.ownAccepted?'Ready when you are':'Meet your group'}</h3><p class="friend-match-sub">${m.status==='ready'?`${accepted.length+1} confirmed members`:`You + ${m.count} new ${m.count===1?'friend':'friends'} · ${m.count+1} people total`}</p><div class="friend-group-preview">${(m.status==='ready'?accepted:m.members).map(p=>`<span>${friendGroupAvatar(p,'friend-group-photo')}<small>${p.name}</small></span>`).join('')}</div><p class="mini muted">${m.ownAccepted&&pending?`${pending} pending · ${m.status==='ready'?'Your group can continue.':'You can start with accepted members.'}`:`${m.interests.length?m.interests.map(esc).join(' · ')+' · ':''}${esc(m.overlap)}`}</p><div class="row friend-match-actions">${m.status==='ready'?btn('Open group chat',"openFriendGroupChat()",'small'):btn(m.ownAccepted?'View responses':'Review group',"reviewFriendGroup()",'small')}${m.status==='ready'?btn('Group details',"reviewFriendGroup()",'light small'):btn('Not now',"cancelFriendSearch()",'light small')}</div></section>`}
function reviewFriendGroup(id){const m=id?(S.friendMatch?.id===id?S.friendMatch:chatFixtures.find(c=>c.groupId===id)?.group):S.friendMatch;if(!m){toast('This sample group is no longer active');return}show(m.status==='ready'?'Your group':'Meet your group',`<div class="row between"><span class="badge">Friends group · ${m.status==='ready'?m.members.filter(p=>p.response==='accepted').length+1:m.count+1} ${m.status==='ready'?'members':'people'}</span><small>Demo match</small></div><div class="friend-group-reason">${m.interests.length?`<div class="row">${m.interests.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>`:''}<p>${S.profile.visible.overlap?esc(m.overlap)+' · Shared availability':'Availability hidden'}</p></div><div class="friend-group-member"><span class="friend-initial-avatar">${esc(S.name.slice(0,1))}</span><div><b>You</b><small>${m.ownAccepted?'Accepted':'Your response'}</small></div><span class="member-response ${m.ownAccepted?'accepted':''}">${m.ownAccepted?'Accepted':'Not yet'}</span></div>${m.members.map(p=>`<div class="friend-group-member">${friendGroupAvatar(p,'friend-group-photo')}<div><b>${p.name}, ${p.age}</b><small>Campus community</small></div><span class="member-response ${p.response}">${p.response==='accepted'?'Accepted':'Pending'}</span><button class="member-safety" aria-label="Block or report ${p.name}" onclick="safety('${p.name}')">⋯</button></div>`).join('')}<p class="friend-group-note">${m.status==='ready'?'Only confirmed members are in the chat.':'You can start with at least one other accepted member.'} Pending people are not added automatically.</p><div class="row friend-match-actions">${m.status==='ready'?btn('Open group chat',`openFriendGroupChat('${m.id}')`):m.ownAccepted?btn('Start with '+(m.members.filter(p=>p.response==='accepted').length+1),"formFriendGroup()"):btn('Accept group',"acceptFriendGroup()")}${m.status!=='ready'?btn(m.ownAccepted?'Cancel':'Decline',"cancelFriendSearch()",'light'):''}</div>${m.ownAccepted&&m.status!=='ready'?`<button class="text-link" onclick="finishFriendGroup()">Simulate remaining responses</button>`:''}`)}
function acceptFriendGroup(){const m=S.friendMatch;if(!m)return;m.ownAccepted=true;m.status='waiting';render();if(m.members.every(p=>p.response==='accepted')){formFriendGroup();return}reviewFriendGroup()}
function formFriendGroup(){const m=S.friendMatch;if(!m||!m.ownAccepted)return;const accepted=m.members.filter(p=>p.response==='accepted');if(!accepted.length){toast('At least one other person needs to accept');return}accepted.forEach(p=>{if(!S.connections.includes(p.name))S.connections.push(p.name)});m.status='ready';render();reviewFriendGroup()}

function finishFriendGroup(){const m=S.friendMatch;if(!m||!m.ownAccepted)return;m.members.forEach(p=>{p.response='accepted';if(!S.connections.includes(p.name))S.connections.push(p.name)});m.status='ready';render();if(modal.open)reviewFriendGroup();else toast('Everyone accepted. Your group chat is ready.')}
function openFriendGroupChat(id){const m=id?(S.friendMatch?.id===id?S.friendMatch:chatFixtures.find(c=>c.groupId===id)?.group):S.friendMatch;if(!m||m.status!=='ready')return;let chat=chatFixtures.find(c=>c.groupId===m.id);if(!chat){chat={id:m.id,groupId:m.id,group:m,memberNames:[S.name,...m.members.filter(p=>p.response==='accepted').map(p=>p.name)],name:defaultGroupName([S.name,...m.members.filter(p=>p.response==='accepted').map(p=>p.name)]),kind:'Friends',time:'Now',unread:0,joinOffsets:{[S.name]:0},history:[{text:'Hey everyone! Happy we connected 👋',mine:false,sender:m.members.find(p=>p.response==='accepted').name,time:'Now'}]};chatFixtures.unshift(chat)}openChat(chat.id)}

// Group growth prototype: explicit ready-up, opt-in newcomers, and per-member history boundaries.
function visibleChatHistory(chat,viewer=S.name){return chat.history.slice(chat.joinOffsets?.[viewer]??0).filter(m=>!m.sender||!S.blocked.includes(m.sender))}
function groupRoster(chat){return [...new Set(chat.memberNames||[S.name,...chat.group.members.filter(p=>p.response==='accepted').map(p=>p.name)])]}
function groupVacancies(chat){return Math.max(0,chat.group.count+1-groupRoster(chat).length)}
function groupGrowthCard(chat){const roster=groupRoster(chat),slots=groupVacancies(chat),g=chat.group.growth||{stage:'idle'},target=chat.group.count+1;if(!slots)return `<section class="group-growth"><div class="row between"><b>${roster.length} of ${target} members</b><span class="badge">Group complete</span></div></section>`;return `<section class="group-growth" aria-label="Group ready-up"><div class="row between"><b>${roster.length} of ${target} members</b><small>${slots} open ${slots===1?'spot':'spots'}</small></div>${g.stage==='idle'?`<p>Ready up together to find more members.</p>${btn('Find '+slots+' more',`beginGroupReady('${chat.id}')`,'small')}`:g.stage==='readying'?`<h3>Ready to find more?</h3><div class="ready-members">${roster.map(name=>`<div><span>${name===S.name?'You':esc(name)}</span><small class="${g.ready[name]?'is-ready':''}">${g.ready[name]?'Ready':'Not ready'}</small></div>`).join('')}</div><div class="row">${btn(g.ready[S.name]?'Not ready':'Ready up',`toggleGroupReady('${chat.id}')`,'small')}${btn('Cancel',`cancelGroupGrowth('${chat.id}')`,'light small')}</div><button class="growth-demo-link" onclick="simulateGroupReady('${chat.id}')">Simulate other members ready</button>`:g.stage==='queued'?`<h3>Looking for ${slots} more…</h3><p>Everyone is ready. Your group stays together.</p><div class="row">${btn('Check now',`findGrowthCandidates('${chat.id}')`,'small')}${btn('Cancel search',`cancelGroupGrowth('${chat.id}')`,'light small')}</div>`:`<h3>New people to review your group</h3><div class="growth-candidates">${(g.candidates||[]).map(person=>`<div class="growth-candidate">${friendGroupAvatar(person,'inbox-avatar')}<span><b>${person.name}</b><small>${person.response==='accepted'?'Joined':person.response==='declined'?'Declined':'Review pending'}</small></span>${person.response==='pending'?`<button class="text-link" onclick="reviewAsNewcomer('${chat.id}','${person.name}')">Preview review</button>`:person.response==='accepted'?`<button class="text-link" onclick="previewNewcomerHistory('${chat.id}','${person.name}')">Preview chat</button>`:''}</div>`).join('')}</div>${g.stage==='empty'?'<p>No eligible sample people found. Try another search.</p>':''}${btn('Cancel search',`cancelGroupGrowth('${chat.id}')`,'light small')}`}</section>`}
function growthChat(id){return chatFixtures.find(c=>c.id===id&&c.groupId)}
function beginGroupReady(id){if(!ACTIVE_FRIEND_MATCHMAKING)return;const chat=growthChat(id);if(!chat||!groupVacancies(chat))return;chat.group.growth={stage:'readying',ready:Object.fromEntries(groupRoster(chat).map(name=>[name,false])),candidates:[],token:(chat.group.growth?.token||0)+1};render();scrollChat()}
function toggleGroupReady(id){const chat=growthChat(id),g=chat?.group.growth;if(!g||g.stage!=='readying')return;g.ready[S.name]=!g.ready[S.name];maybeQueueGroup(chat);render();scrollChat()}
function simulateGroupReady(id){const chat=growthChat(id),g=chat?.group.growth;if(!g||g.stage!=='readying')return;groupRoster(chat).forEach(name=>{if(name!==S.name)g.ready[name]=true});maybeQueueGroup(chat);render();scrollChat()}
function maybeQueueGroup(chat){const g=chat.group.growth;if(!groupRoster(chat).every(name=>g.ready[name]))return;g.stage='queued';const token=++g.token;setTimeout(()=>{if(g.stage==='queued'&&g.token===token)findGrowthCandidates(chat.id)},2400)}
function cancelGroupGrowth(id){const chat=growthChat(id);if(!chat)return;const token=(chat.group.growth?.token||0)+1;chat.group.growth={stage:'idle',ready:{},candidates:[],token};modal.close();render();scrollChat()}
function findGrowthCandidates(id){const chat=growthChat(id),g=chat?.group.growth;if(!g||g.stage!=='queued'||!groupRoster(chat).every(name=>g.ready[name]))return;const target=chat.group.count+1,roster=groupRoster(chat),ages=chat.group.searchFilters?.ages||[18,80];g.candidates=friendGroupPeople.filter(p=>AccountUI.allowed(p.name)&&p.queued&&p.allowExistingGroups&&!roster.includes(p.name)&&p.age>=ages[0]&&p.age<=ages[1]&&target>=p.minGroupSize&&target<=p.maxGroupSize).slice(0,groupVacancies(chat)).map(p=>({...p,response:'pending'}));g.stage=g.candidates.length?'review':'empty';render();if(S.chatId===id)scrollChat()}
function reviewAsNewcomer(id,name){const chat=growthChat(id),g=chat?.group.growth,p=g?.candidates.find(p=>p.name===name);if(!p||p.response!=='pending'||g.stage!=='review')return;show('Join this group?',`<span class="badge">Demo · Viewing as ${name}</span><h3 class="section">${groupRoster(chat).length} members · Growing to ${chat.group.count+1}</h3><div class="newcomer-roster">${groupRoster(chat).map(member=>`<div class="friend-group-member"><span class="friend-initial-avatar">${esc(member.slice(0,1))}</span><div><b>${esc(member)}</b><small>Already in group</small></div><span class="member-response accepted">Ready</span></div>`).join('')}</div><p class="mini muted section">${S.profile.visible.overlap?esc(chat.group.overlap)+' · Shared interests':'Shared interests'}<br>You’ll see messages sent from when you join.</p><div class="row">${btn('Accept & join',`acceptGrowthCandidate('${id}','${name}')`)}${btn('Decline',`declineGrowthCandidate('${id}','${name}')`,'light')}</div>`)}
function acceptGrowthCandidate(id,name){const chat=growthChat(id),g=chat?.group.growth,p=g?.candidates.find(p=>p.name===name);if(!p||p.response!=='pending'||g.stage!=='review'||!groupVacancies(chat))return;if(!p.allowExistingGroups||groupRoster(chat).includes(name))return;p.response='accepted';const existing=chat.group.members.find(m=>m.name===name);if(existing)existing.response='accepted';else chat.group.members.push({...p,response:'accepted'});chat.joinOffsets??={};chat.joinOffsets[name]=chat.history.length;chat.history.push({system:true,text:name+' joined the group',time:'Now'});chat.memberNames=[...new Set([...groupRoster(chat),name])];if(!chat.customGroupName)chat.name=defaultGroupName(chat.memberNames);chat.time='Now';g.ready[name]=true;if(!groupVacancies(chat))g.stage='full';modal.close();render();scrollChat();show('Joined the group',`<p>${name} is in the existing chat. Earlier messages remain private.</p><div class="row">${btn('Preview '+name+'’s chat',`previewNewcomerHistory('${id}','${name}')`)}${btn('Back to your chat',"modal.close()",'light')}</div>`)}
function declineGrowthCandidate(id,name){const chat=growthChat(id),g=chat?.group.growth,p=g?.candidates.find(p=>p.name===name);if(!p||p.response!=='pending'||g.stage!=='review')return;p.response='declined';if(g.candidates.every(p=>p.response!=='pending'))g.stage='empty';modal.close();render();scrollChat()}
function previewNewcomerHistory(id,name){const chat=growthChat(id);if(!chat||chat.joinOffsets?.[name]===undefined)return;show(name+'’s conversation',`<span class="badge">Demo · New member view</span><p class="mini muted section">Messages from when ${name} joined. Earlier history is private.</p><div class="newcomer-history">${visibleChatHistory(chat,name).map(m=>m.system?`<div class="chat-system">${esc(m.text)}</div>`:`<div class="chatbubble">${esc(m.text)}</div>`).join('')}</div>${btn('Back to your chat',"modal.close()",'light')}`)}
function offerExistingGroup(count){S.queue=false;S.friendQueueToken=(S.friendQueueToken||0)+1;S.existingGroupOffer={id:'existing-'+S.friendQueueToken,target:count+1,members:friendGroupPeople.filter(p=>AccountUI.allowed(p.name)&&p.queued&&p.allowExistingGroups&&p.age>=S.friendSearchFilters.ages[0]&&p.age<=S.friendSearchFilters.ages[1]).slice(0,2),status:'pending'};render()}
function existingOfferCard(){const offer=S.existingGroupOffer;return `<section class="friend-match-card"><span class="badge">Existing group</span><h3>A circle with room for you</h3><p>${offer.members.length} members · Up to ${offer.target} total</p><div class="friend-group-preview">${offer.members.map(p=>`<span>${friendGroupAvatar(p,'friend-group-photo')}<small>${p.name}</small></span>`).join('')}</div>${btn('Review group',"reviewExistingOffer()",'small')}</section>`}
function reviewExistingOffer(){const offer=S.existingGroupOffer;if(!offer||!S.allowExistingGroups)return;show('Join this group?',`<span class="badge">Existing group</span><h3 class="section">${offer.members.length} members · Growing to ${offer.target}</h3>${offer.members.map(p=>`<div class="friend-group-member">${friendGroupAvatar(p,'friend-group-photo')}<div><b>${p.name}</b><small>Already in group</small></div><span class="member-response accepted">Ready</span></div>`).join('')}<p class="mini muted section">Everyone is ready to welcome new members. You’ll only see messages sent from when you join.</p><div class="row">${btn('Accept & join',"acceptExistingOffer()")}${btn('Decline',"S.existingGroupOffer=null;modal.close();render()",'light')}</div>`)}
function acceptExistingOffer(){const offer=S.existingGroupOffer;if(!offer||!S.allowExistingGroups)return;const group={id:offer.id,count:offer.target-1,status:'ready',ownAccepted:true,interests:[...S.interests.slice(0,2)],overlap:'A shared time window',members:offer.members.map(p=>({...p,response:'accepted'})),searchFilters:{ages:[...S.ageRanges.Friends],area:S.areas.Friends,radius:S.radii.Friends}};const history=[{text:'Earlier private planning between existing members.',sender:offer.members[0].name,mine:false,time:'Yesterday'}];const chat={id:group.id,groupId:group.id,group,name:defaultGroupName([S.name,...offer.members.map(p=>p.name)]),kind:'Friends',memberNames:[S.name,...offer.members.map(p=>p.name)],time:'Now',unread:0,joinOffsets:{[S.name]:history.length},history};chat.history.push({system:true,text:S.name+' joined the group',time:'Now'});chatFixtures.unshift(chat);S.friendMatch=group;S.existingGroupOffer=null;openChat(chat.id)}
